      ACCEPTANCE_FAKE_HARDWARE_READINESS: "true",
      SPRING_APPLICATION_JSON: JSON.stringify({
        led: {
          outputs: [
            { name: "bridge", enabled: false, host: "127.0.0.1", port: 3001 },
