package com.ledgame.service;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.ledgame.entity.Game;
import java.util.ArrayList;
import java.util.List;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Creates the editable Simple game variants without overwriting user data.
 */
@Service
public class SimpleGameVariantSeedService {
    public static final List<String> VARIANT_NAMES = List.of("simple", "normal", "diffcult");

    private final GameService gameService;
    private final SimpleDemoGameFactory factory;
    private final SimpleDemoSeedService simpleDemoSeedService;

    public SimpleGameVariantSeedService(
            GameService gameService,
            SimpleDemoGameFactory factory,
            SimpleDemoSeedService simpleDemoSeedService) {
        this.gameService = gameService;
        this.factory = factory;
        this.simpleDemoSeedService = simpleDemoSeedService;
    }

    @Transactional
    public List<Game> seed() {
        List<Game> games = new ArrayList<>();
        games.add(simpleDemoSeedService.seed());
        for (String name : VARIANT_NAMES) {
            games.add(seedVariant(name));
        }
        return List.copyOf(games);
    }

    private Game seedVariant(String name) {
        List<Game> existing = gameService.list(new LambdaQueryWrapper<Game>()
                .eq(Game::getName, name));
        if (existing.size() > 1) {
            throw new IllegalStateException("duplicate Simple game variant records: " + name);
        }
        if (existing.size() == 1) {
            Game game = existing.get(0);
            if (!factory.isExpectedSimpleGame(game, name)) {
                throw new IllegalStateException("unexpected Simple game variant structure: " + name);
            }
            return game;
        }

        Game game = factory.createGame(name);
        gameService.save(game);
        return game;
    }
}

