package com.ledgame.service;

import com.ledgame.dto.editor.GameEditorDocument;
import com.ledgame.dto.editor.GameEditorSaveResponse;
import com.ledgame.dto.editor.GameEditorValidationResult;
import com.ledgame.GameApp.Runtime.media.GameMediaProfileFactory;
import com.ledgame.entity.Game;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class GameEditorService {
    private final GameService gameService;
    private final GameEditorAssembler assembler;
    private final GameEditorValidator validator;
    private final GameMediaProfileFactory mediaProfileFactory;

    public GameEditorService(GameService gameService, GameEditorAssembler assembler, GameEditorValidator validator) {
        this(gameService, assembler, validator, null);
    }

    @Autowired
    public GameEditorService(
            GameService gameService,
            GameEditorAssembler assembler,
            GameEditorValidator validator,
            GameMediaProfileFactory mediaProfileFactory) {
        this.gameService = gameService;
        this.assembler = assembler;
        this.validator = validator;
        this.mediaProfileFactory = mediaProfileFactory;
    }

    public GameEditorDocument getDetail(Long gameId) {
        Game game = gameService.getById(gameId);
        if (game == null) {
            throw new IllegalArgumentException("游戏不存在: " + gameId);
        }
        requireSimpleGame(game);
        return assembler.toDocument(game);
    }

    public GameEditorValidationResult validate(GameEditorDocument document) {
        GameEditorValidationResult result = validator.validate(document);
        if (document == null || mediaProfileFactory == null) {
            return result;
        }
        Game mediaGame = assembler.applyToGame(document, new Game());
        preserveLegacyFallback(document.getId(), mediaGame);
        result.setMediaDiagnostics(mediaProfileFactory.create(mediaGame).diagnostics());
        return result;
    }

    @Transactional
    public GameEditorSaveResponse save(GameEditorDocument document) {
        GameEditorValidationResult result = validator.validate(document);
        if (result.hasErrors()) {
            throw new IllegalArgumentException(result.getErrors().get(0).message());
        }

        if (document.getId() == null) {
            throw new IllegalArgumentException("编辑器只能保存已有游戏");
        }

        Game target = gameService.getById(document.getId());
        if (target == null) {
            throw new IllegalArgumentException("游戏不存在: " + document.getId());
        }
        requireSimpleGame(target);

        Game game = assembler.applyToGame(document, target);
        gameService.updateById(game);
        return new GameEditorSaveResponse(game.getId(), true);
    }

    private void requireSimpleGame(Game game) {
        if ("rank".equals(game.getType())) {
            throw new IllegalArgumentException("游戏不是 Simple 编辑器支持的类型: "
                    + game.getType() + "/" + game.getMode());
        }
    }

    private void preserveLegacyFallback(Long gameId, Game mediaGame) {
        if (gameId == null) {
            return;
        }
        Game existing = gameService.getById(gameId);
        if (existing != null) {
