      await store.registerAndBind({ phone: "13800000025", name: "验收会员二十五", uid: "2283055624" });
      await store.startGame("2283055623");
      await store.enqueueNextGame("2283055624");
    });
    await test.step("重启会员管理后端并验证房间和队列恢复", async () => {
