        }
        if ("mix".equals(game.getType())) {
            this.gameService.updateMixLevelRefNum();
        }
        return AjaxResult.success((Object)game.getId());
    }

    private void checkQuestionBankFormat(Game game) throws IOException {
        String gameType = game.getType();
        String levelStr = game.getLevels();
        if (StringUtils.isBlank((CharSequence)levelStr)) {
            return;
        }
        if ("basketball".equals(gameType)) {
            JSONArray levels = JSON.parseArray((String)levelStr);
            for (Object _level : levels) {
                JSONObject level = (JSONObject)_level;
                JSONObject option = level.getJSONObject("option");
                Integer mode = option.getInteger("mode");
                boolean enableTTS = option.getBooleanValue("enableTTS");
                String questionBank = option.getString("questionBank");
                if (mode == null || mode != 6 || !StringUtils.isNotBlank((CharSequence)questionBank)) continue;
                List<String> lines = Files.readAllLines(Paths.get(this.filesDir + questionBank, new String[0]));
                lines = lines.stream().filter(StringUtils::isNotBlank).filter(x -> !x.startsWith("--")).collect(Collectors.toList());
                int lineNum = 0;
                ArrayList<String> voiceContents = new ArrayList<String>();
                while (lineNum < lines.size()) {
                    String answer;
                    String line;
                    boolean _enableTTS;
                    if (_enableTTS = (line = lines.get(lineNum++)).endsWith("[V]") ? true : (line.endsWith("[M]") ? false : enableTTS)) {
                        String voiceContent;
                        if (StringUtils.isBlank((CharSequence)(voiceContent = lines.get(lineNum++))) || voiceContent.startsWith("A.") || voiceContent.startsWith("B.") || voiceContent.startsWith("C.") || voiceContent.startsWith("D.")) {
                            throw new ClientException("error format, line[" + lineNum + "]: " + lines.get(lineNum - 1));
                        }
                        voiceContents.add(voiceContent);
                    }
                    if (!("A".equals(answer = lines.get(lineNum++)) || "B".equals(answer) || "C".equals(answer) || "D".equals(answer))) {
                        throw new ClientException("error format, line[" + lineNum + "]: " + lines.get(lineNum - 1));
                    }
                    if (!lines.get(lineNum++).startsWith("A.")) {
                        throw new ClientException("error format, line[" + lineNum + "]: " + lines.get(lineNum - 1));
                    }
                    if (!lines.get(lineNum++).startsWith("B.")) {
                        throw new ClientException("error format, line[" + lineNum + "]: " + lines.get(lineNum - 1));
                    }
                    if (!lines.get(lineNum++).startsWith("C.")) {
                        throw new ClientException("error format, line[" + lineNum + "]: " + lines.get(lineNum - 1));
                    }
                    if (lines.get(lineNum++).startsWith("D.")) continue;
                    throw new ClientException("error format, line[" + lineNum + "]: " + lines.get(lineNum - 1));
                }
                if (voiceContents.isEmpty()) continue;
                String voiceName = option.getString("voiceName");
                String store = SpringUtil.getProperty((String)"files.directory") + "system" + File.separator + "tts";
                TTSUtils.batchTrans((String)voiceName, (String)store, voiceContents);
            }
        } else if ("UnityDefault".equals(gameType) || "UnityDefault2".equals(gameType)) {
            JSONArray levels = JSON.parseArray((String)levelStr);
            for (Object _level : levels) {
                JSONArray questions;
                JSONObject level = (JSONObject)_level;
                JSONObject option = level.getJSONObject("option");
                boolean enableTTS = option.getBooleanValue("enableTTS");
                String voiceName = option.getString("voiceName");
                String locale = option.getString("locale");
                if (StringUtils.isNotBlank((CharSequence)option.getString("mathExprSimple"))) {
                    questions = this.parseQuestions(option.getString("mathExprSimple"), 0, enableTTS, voiceName, locale);
                    option.put((Object)"simpleQuestions", (Object)questions);
                }
                if (StringUtils.isNotBlank((CharSequence)option.getString("mathExprDefault"))) {
                    questions = this.parseQuestions(option.getString("mathExprDefault"), 1, enableTTS, voiceName, locale);
                    option.put((Object)"defaultQuestions", (Object)questions);
                }
                if (!StringUtils.isNotBlank((CharSequence)option.getString("mathExprDifficulty"))) continue;
                questions = this.parseQuestions(option.getString("mathExprDifficulty"), 2, enableTTS, voiceName, locale);
                option.put((Object)"difficultyQuestions", (Object)questions);
            }
            game.setLevels(levels.toJSONString(new JSONWriter.Feature[0]));
        }
    }

    private JSONArray parseQuestions(String text, int difficulty, boolean enableTTS, String voiceName, String locale) throws IOException {
        JSONArray questions = new JSONArray();
        List mathematicalExpressions = Arrays.stream(text.split("\n")).filter(StringUtils::isNotBlank).map(String::trim).filter(StringUtils::isNotBlank).collect(Collectors.toList());
        List voiceContents = mathematicalExpressions.stream().map(x -> {
            if ("zh-CN".equalsIgnoreCase(locale)) {
                return x.replace("+", "\u52a0").replace("-", "\u51cf").replace("*", "\u4e58").replace("/", "\u9664\u4ee5") + " \u7b49\u4e8e\u591a\u5c11";
            }
            if ("en-US".equals(locale)) {
                return "What is " + x.replace("+", "plus").replace("-", "minus").replace("*", "times").replace("/", "divided by");
            }
            return null;
        }).collect(Collectors.toList());
        List audios = null;
        if (enableTTS && !voiceContents.isEmpty()) {
            String store = SpringUtil.getProperty((String)"files.directory") + "system" + File.separator + "tts";
            int length = SpringUtil.getProperty((String)"files.directory").length();
            audios = TTSUtils.batchTrans((String)voiceName, (String)store, voiceContents);
            audios = audios.stream().map(x -> x.substring(length)).collect(Collectors.toList());
        }
        for (int i = 0; i < mathematicalExpressions.size(); ++i) {
            Object answer;
            String origin = (String)mathematicalExpressions.get(i);
            String format = origin.replace("*", "\u00d7").replace("/", "\u00f7");
            String voiceContent = (String)voiceContents.get(i);
            String audio = null;
            if (audios != null) {
                audio = (String)audios.get(i);
            }
            if ((answer = AviatorEvaluator.execute((String)origin)) == null) {
                throw new RuntimeException("Mathematical expression execution exception: " + origin);
            }
            JSONObject json = new JSONObject();
            json.put((Object)"origin", (Object)origin);
            json.put((Object)"format", (Object)format);
            json.put((Object)"voiceContent", (Object)voiceContent);
            json.put((Object)"audio", (Object)audio);
            json.put((Object)"answer", answer);
            json.put((Object)"difficulty", (Object)difficulty);
            questions.add((Object)json);
        }
        return questions;
    }

    private void genLevelStartGIF(Game game) {
        if (StringUtils.isBlank((CharSequence)game.getLevels())) {
            return;
        }
        JSONArray levels = JSON.parseArray((String)game.getLevels());
        Integer width = game.getSiteSizeWidth();
        Integer height = game.getSiteSizeHeight();
        for (int i = 0; i < levels.size(); ++i) {
            String flashing;
            JSONObject level = levels.getJSONObject(i);
            if ("climbing".equals(game.getType())) {
                flashing = GIFUtils.genFlashing((int)width, (int)height, (int)100, (int)1000);
                log.info("\u751f\u6210\u5173\u5361\u5f00\u59cb\u52a8\u753b game id = {}, levelIndex = {}, gif = {}", new Object[]{game.getId(), i, flashing});
                level.getJSONObject("option").put((Object)"startGIF", (Object)flashing);
                continue;
            }
            if ("throwing".equals(game.getType())) {
                flashing = GIFUtils.genFlashing((int)width, (int)height, (int)100, (int)1000);
                log.info("\u751f\u6210\u5173\u5361\u5f00\u59cb\u52a8\u753b game id = {}, levelIndex = {}, gif = {}", new Object[]{game.getId(), i, flashing});
                level.getJSONObject("option").put((Object)"startGIF", (Object)flashing);
                continue;
            }
            if ("demonEye".equals(game.getType())) {
                flashing = GIFUtils.genFlashing((int)width, (int)(height / 2), (int)200, (int)2000, (Color)new Color(0, 254, 0));
                log.info("\u751f\u6210\u5173\u5361\u5f00\u59cb\u52a8\u753b game id = {}, levelIndex = {}, gif = {}", new Object[]{game.getId(), i, flashing});
                level.getJSONObject("option").put((Object)"startGIF", (Object)flashing);
                continue;
            }
            if ("basketball".equals(game.getType()) || "battle".equals(game.getType())) continue;
            if ("mix".equals(game.getType())) {
                if (level.getJSONObject("mixLevel").getIntValue("mode") != 1) continue;
                try {
                    flashing = GIFUtils.getSingleColorGIF((RGB)RGB.GREEN, (int)width, (int)height, (int)3000);
                    log.info("\u751f\u6210\u5173\u5361\u5f00\u59cb\u52a8\u753b game id = {}, levelIndex = {}, gif = {}", new Object[]{game.getId(), i, flashing});
                    JSONObject option = level.getJSONObject("option");
                    if (option == null) {
                        option = new JSONObject();
                        level.put((Object)"option", (Object)option);
                    }
                    option.put((Object)"startGIF", (Object)flashing);
                }
                catch (Exception flashing2) {}
                continue;
            }
            if ("laser".equals(game.getType()) || "rank".equals(game.getType()) || "memory2".equals(game.getType()) || "flashDefault".equals(game.getType()) || "flashRank".equals(game.getType()) || "ExtremeControlDefault".equals(game.getType()) || "ExtremeControlRank".equals(game.getType()) || "UnityDefault".equals(game.getType()) || "UnityPK".equals(game.getType()) || "UnityDefault2".equals(game.getType()) || "UnityPK2".equals(game.getType()) || "bbbRank".equals(game.getType()) || "bbbPK".equals(game.getType()) || "PipelineDefault".equals(game.getType()) || "PipelinePK".equals(game.getType()) || "FootballDefault".equals(game.getType()) || "FootballPK".equals(game.getType()) || "TurntableDefault".equals(game.getType()) || "TurntablePK".equals(game.getType())) continue;
            ArrayList target = new ArrayList();
            level.getJSONArray("frameList").getJSONObject(0).getJSONArray("matrix").stream().map(x -> (JSONArray)x).forEach(x -> {
                JSONObject jsonSpirit = x.getJSONObject(3);
                if (jsonSpirit.getIntValue("color") == 0) {
                    JSONArray _points = jsonSpirit.getJSONArray("points");
                    _points.stream().map(y -> (JSONArray)y).map(y -> {
                        XY xy = new XY(x.getIntValue(0) + y.getIntValue(0), x.getIntValue(1) + y.getIntValue(1));
                        return xy;
                    }).filter(xy -> xy.getX() >= 0 && xy.getX() < width && xy.getY() >= 0 && xy.getY() < height).forEach(target::add);
                }
            });
            if (target.isEmpty()) continue;
            String codeRain = GIFUtils.genCodeRainGIF((int)width, (int)height, (int)20, (int)3500, target, (long)game.getId(), (int)i);
            log.info("\u751f\u6210\u5173\u5361\u5f00\u59cb\u52a8\u753b game id = {}, levelIndex = {}, gif = {}", new Object[]{game.getId(), i, codeRain});
            level.getJSONObject("option").put((Object)"startGIF", (Object)codeRain);
        }
        game.setLevels(JSON.toJSONString((Object)levels));
    }

