        }
        game.setId(id);
        game.setVersion(Integer.valueOf(5));
        game.setUpdateTime(new Date());
        game.setLevelPreparationTime(Integer.valueOf(3));
        this.fillVoiceDescLength(game);
        this.genLevelStartGIF(game);
        if (game.getTouchShow() == null) {
            game.setTouchShow(Boolean.TRUE);
        }
        this.checkQuestionBankFormat(game);
        this.gameService.updateById((Object)game);
        GIFUtils.genCountdown((int)game.getSiteSizeWidth(), (int)game.getSiteSizeHeight());
        if ("mix".equals(game.getType())) {
            this.gameService.updateMixLevelRefNum();
        }
        PixelLightDisplayUtils.clearCache();
        return AjaxResult.success();
    }

    private void fillVoiceDescLength(Game game) throws Exception {
        if (StringUtils.isNotBlank((CharSequence)game.getLevels())) {
            JSONArray levels = JSON.parseArray((String)game.getLevels());
            for (Object _level : levels) {
                JSONObject level = (JSONObject)_level;
                JSONObject option = level.getJSONObject("option");
                if (option == null) continue;
                String voiceDesc = option.getString("voiceDesc");
                if (StringUtils.isNotBlank((CharSequence)voiceDesc)) {
                    int duration = AudioUtils.getDuration((String)AudioUtils.formatFileName2((String)voiceDesc));
                    option.put((Object)"voiceDescLength", (Object)duration);
                    continue;
                }
                option.put((Object)"voiceDescLength", (Object)0);
            }
            game.setLevels(JSON.toJSONString((Object)levels));
        }
    }

