    @GetMapping(value={"exportGame/{id}"})
    public void exportGame(@PathVariable Long id, HttpServletResponse response) {
        Triplet triplet;
        Game game = (Game)this.gameService.getById((Serializable)id);
        try {
            triplet = this.getDependFiles(game, false);
        }
        catch (FileNotFoundException e) {
            ServletUtil.write((HttpServletResponse)response, (String)String.format("[%s] \u6587\u4ef6\u4e0d\u5b58\u5728!\n\n[%s] File not exist!", e.getMessage(), e.getMessage()), (String)"text/plain;charset=utf-8");
            return;
        }
        List filtered = (List)triplet.getValue0();
        List mixLevels = (List)triplet.getValue1();
        List rhythmMasters = (List)triplet.getValue2();
        List spirits = this.spiritService.list();
        response.setContentType("application/zip");
        String fileName = "files.zip";
        if (StringUtils.isNotBlank((CharSequence)game.getName())) {
            fileName = URLEncodeUtil.encode((String)game.getName()) + ".zip";
        }
        response.setHeader("Content-Disposition", "attachment; filename=\"" + fileName + "\"");
        try (ZipOutputStream zipOut = new ZipOutputStream((OutputStream)response.getOutputStream());){
            for (String file : filtered) {
                this.addToZipFile(file, zipOut);
            }
            Files.deleteIfExists(Paths.get(this.filesDir + "Game.json", new String[0]));
            Files.deleteIfExists(Paths.get(this.filesDir + "Spirits.json", new String[0]));
            Files.deleteIfExists(Paths.get(this.filesDir + "MixLevels.json", new String[0]));
