    private Triplet<List<String>, List<MixLevel>, List<RhythmMaster>> getDependFiles(Game game, boolean skipAutoGen) throws FileNotFoundException {
        List files = this.parseAllFiles(game);
        ArrayList mixLevels = new ArrayList();
        ArrayList rhythmMasters = new ArrayList();
        if (StringUtils.isNotBlank((CharSequence)game.getLevels())) {
            JSONArray levels = JSON.parseArray((String)game.getLevels());
            if ("mix".equalsIgnoreCase(game.getType())) {
                levels.stream().map(x -> (JSONObject)x).map(x -> x.getLong("id")).filter(Objects::nonNull).forEach(x -> {
                    MixLevel mixLevel = (MixLevel)this.mixLevelService.getById((Serializable)x);
                    if (mixLevel != null) {
                        mixLevels.add(mixLevel);
                        if (StringUtils.isNotBlank((CharSequence)mixLevel.getBgm())) {
                            files.add(mixLevel.getBgm());
                        }
                        if ("rhythm_master".equalsIgnoreCase(mixLevel.getType()) || "rhythm_master2".equalsIgnoreCase(mixLevel.getType())) {
                            Long rhythm = JSON.parseObject((String)mixLevel.getCommonConfig()).getLong("rhythm");
                            RhythmMaster rhythmMaster = (RhythmMaster)this.rhythmMasterService.getById((Serializable)rhythm);
                            rhythmMasters.add(rhythmMaster);
                            files.add(rhythmMaster.getFile());
                        }
                    }
                });
            }
        }
        List filtered = files.stream().filter(StringUtils::isNotBlank).distinct().collect(Collectors.toList());
        ArrayList<String> notFoundFiles = new ArrayList<String>();
        for (String fileName : filtered) {
            if (skipAutoGen && (fileName.startsWith("system" + File.separator) || fileName.startsWith("gif" + File.separator))) continue;
            log.info("\u6821\u9a8c\u6587\u4ef6 {}", (Object)fileName);
            if (FileUtil.exist((String)(this.filesDir + fileName))) continue;
            log.info("\u6587\u4ef6 {} \u4e0d\u5b58\u5728", (Object)fileName);
            notFoundFiles.add(fileName);
        }
        if (!notFoundFiles.isEmpty()) {
            throw new FileNotFoundException(notFoundFiles.stream().collect(Collectors.joining("\u3001")));
        }
        return Triplet.with(filtered, mixLevels, rhythmMasters);
    }

    private List<String> parseAllFiles(Game game) {
        String str = JSON.toJSONString((Object)game);
        ArrayList<String> files = new ArrayList();
        this.traverseJson((Object)JSON.parseObject((String)str), files);
        files = files.stream().distinct().collect(Collectors.toList());
        if (StringUtils.isNotBlank((CharSequence)game.getFirstCatalog())) {
            Catalog firstCatalog = (Catalog)this.catalogMapper.selectById((Serializable)((Object)game.getFirstCatalog()));
            files.add(firstCatalog.getImage());
        }
        return files;
    }

    private void traverseJson(Object obj, List<String> files) {
        if (obj instanceof JSONObject) {
            JSONObject jsonObject = (JSONObject)obj;
            for (String key : jsonObject.keySet()) {
                Object value = jsonObject.get(key);
                this.traverseJson(value, files);
            }
        } else if (obj instanceof JSONArray) {
            JSONArray jsonArray = (JSONArray)obj;
            for (Object item : jsonArray) {
                this.traverseJson(item, files);
            }
        } else if (obj instanceof String && (JSON.isValidArray((String)((String)obj)) || JSON.isValidObject((String)((String)obj)))) {
            System.out.println(obj);
            this.traverseJson(JSON.parse((String)((String)obj)), files);
        } else if (obj instanceof String && this.isFile((String)obj)) {
            files.add((String)obj);
        }
    }

    private boolean isFile(String name) {
        return (name = name.toLowerCase()).endsWith(".jpg") || name.endsWith(".jpeg") || name.endsWith(".png") || name.endsWith(".gif") || name.endsWith(".mp3") || name.endsWith(".wav") || name.endsWith(".ogg") || name.endsWith(".txt") || name.endsWith(".mov") || name.endsWith(".mp4");
    }

