    @GetMapping(value={"exportAsGIF/{id}/{index}"})
    public void exportAsGIF(@PathVariable Long id, @PathVariable(value="index") Integer index, HttpServletResponse response) {
        Game game = (Game)this.gameService.getById((Serializable)id);
        int w = game.getSiteSizeWidth();
        int h = game.getSiteSizeHeight();
        Color[] ColorArray = new Color[]{Color.GREEN, Color.BLUE, Color.RED, Color.MAGENTA};
        JSONObject level = JSON.parseArray((String)game.getLevels()).getJSONObject(index.intValue());
        int defaultRepeatTimes = level.getIntValue("frameDefaultRepeatTimes");
        JSONArray frameList = level.getJSONArray("frameList");
        String filename = UUID.randomUUID() + ".gif";
        AnimatedGifEncoder e = new AnimatedGifEncoder();
        e.setQuality(1);
        e.start(SpringUtil.getProperty((String)"files.directory") + File.separator + filename);
        frameList.stream().map(x -> (JSONObject)x).forEach(frame -> {
            BufferedImage image = new BufferedImage(w, h, 1);
            Graphics2D g = image.createGraphics();
            g.setColor(Color.BLACK);
            g.fillRect(0, 0, w, h);
            JSONArray matrix = frame.getJSONArray("matrix");
            matrix.stream().map(y -> (JSONArray)y).forEach(sprite -> {
                int x = sprite.getIntValue(0);
                int y = sprite.getIntValue(1);
                JSONObject _3 = sprite.getJSONObject(3);
                int color = _3.getIntValue("color");
                JSONArray points = _3.getJSONArray("points");
                points.stream().map(z -> (JSONArray)z).forEach(point -> {
                    int _x = point.getIntValue(0);
                    int _y = point.getIntValue(1);
                    image.setRGB(x + _x, y + _y, ColorArray[color].getRGB());
                });
            });
            g.dispose();
            Integer repeatTimes = frame.getInteger("repeatTimes");
            if (repeatTimes == null) {
                repeatTimes = defaultRepeatTimes;
            }
            e.setDelay(repeatTimes * 25);
            e.addFrame(image);
        });
        e.finish();
        log.info("\u5173\u5361GIF\u6587\u4ef6\u751f\u6210\u6210\u529f file = {}", (Object)filename);
        try {
            response.setContentType("image/gif");
            response.setHeader("Content-Disposition", "attachment; filename=\"" + filename + "\"");
            ServletOutputStream os = response.getOutputStream();
            os.write(Files.readAllBytes(Paths.get(this.filesDir + filename, new String[0])));
            os.flush();
        }
        catch (Exception e1) {
            log.error("\u6587\u4ef6\u4e0b\u8f7d\u5931\u8d25", (Throwable)e1);
        }
    }

