            game.setMode("[2]");
        }
        if (batchs != null && !batchs.isEmpty() && (count = (int)batchs.stream().filter(x -> x.getType() == 2).count()) == batchs.size()) {
            int minTimeMillis = batchs.stream().map(x -> {
                if (x.getEndTime() == null) {
                    return x.getDurationMinutes().longValue() * 60L * 1000L;
                }
                return x.getEndTime().getTime() - System.currentTimeMillis();
            }).min(Long::compareTo).orElse(0L).intValue();
            game.setGlobalTimeLimitValue(Integer.valueOf(Math.min(game.getGlobalTimeLimitValue() * 1000, minTimeMillis) / 1000));
        }
        long s1 = System.currentTimeMillis();
        GameContext context = new GameContext();
        context.setLanguage(language);
