package com.ledgame.platform;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.Set;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/** Ephemeral presence for the old game client, whose only identity is its socket IP. */
@Service
public class LegacyRoomPresenceService {
    private static final Duration ONLINE_WINDOW = Duration.ofSeconds(60);
    private final JdbcTemplate jdbc;
    private final Clock clock;
    private final ProtectedDataService protectedData;
    private final ConcurrentMap<String, Instant> lastSeenByIp = new ConcurrentHashMap<>();
    private final Set<String> registeredThisProcess = ConcurrentHashMap.newKeySet();

    public LegacyRoomPresenceService(JdbcTemplate jdbc, Clock clock, ProtectedDataService protectedData) {
        this.jdbc = jdbc;
        this.clock = clock;
        this.protectedData = protectedData;
    }

    public String heartbeat(String rawIp) {
        String ip = RoomConnectionRegistry.normalizeIp(rawIp);
        if (registeredThisProcess.add(ip)) {
            String now = clock.instant().toString();
            jdbc.update("""
                    INSERT INTO room_settings(room_ip, display_name, created_at, updated_at)
                    VALUES (?, ?, ?, ?) ON CONFLICT(room_ip) DO NOTHING
                    """, ip, ip, now, now);
        }
        lastSeenByIp.put(ip, clock.instant());
        return ip;
    }

    public List<Map<String, Object>> list() {
        Map<String, Map<String, Object>> rooms = new LinkedHashMap<>();
        for (String ip : jdbc.queryForList(
                "SELECT DISTINCT room_ip FROM legacy_game_sessions ORDER BY room_ip", String.class)) {
            rooms.put(ip, projection(ip));
        }
        for (String ip : lastSeenByIp.keySet()) rooms.put(ip, projection(ip));
        return rooms.values().stream()
                .sorted(Comparator.comparing(room -> String.valueOf(room.get("ip"))))
                .toList();
    }

    public Map<String, Object> find(String rawIp) {
        String ip = RoomConnectionRegistry.normalizeIp(rawIp);
        boolean known = lastSeenByIp.containsKey(ip)
                || !jdbc.queryForList("SELECT room_ip FROM legacy_game_sessions WHERE room_ip=? LIMIT 1", ip).isEmpty();
        return known ? projection(ip) : null;
    }

    private Map<String, Object> projection(String ip) {
        Instant lastSeen = lastSeenByIp.get(ip);
        Instant now = clock.instant();
        boolean online = lastSeen != null && !lastSeen.isBefore(now.minus(ONLINE_WINDOW));
        List<Map<String, Object>> sessions = jdbc.queryForList("""
                SELECT session_id AS sessionId, game_id AS gameId, game_name AS gameName, started_at AS startedAt
                  FROM legacy_game_sessions WHERE room_ip=? AND status='RUNNING'
                 ORDER BY started_at DESC LIMIT 1
                """, ip);
        Map<String, Object> active = sessions.isEmpty() ? null : sessions.get(0);
        List<Map<String, Object>> players = active == null ? List.of() : players(String.valueOf(active.get("sessionId")));

        LinkedHashMap<String, Object> state = new LinkedHashMap<>();
        state.put("engineState", active == null ? "IDLE" : "RUNNING");
        if (active != null) state.put("gameName", active.get("gameName"));
        state.put("legacyCompatibility", true);
        state.put("hardware", List.of(Map.of(
                "id", "elc408-controller", "name", "ELC-408 controller",
                "location", "Game terminal", "status", "unknown",
                "detail", "Legacy protocol does not report controller health")));

        LinkedHashMap<String, Object> result = new LinkedHashMap<>();
        result.put("ip", ip);
        result.put("deviceId", ip);
        result.put("roomId", ip);
        result.put("roomName", ip);
        result.put("connectionId", "legacy:" + ip);
        result.put("online", online);
        result.put("state", state);
        result.put("lastSequence", -1L);
        result.put("lastEventType", active == null ? "LEGACY_HEARTBEAT" : "LEGACY_GAME_STARTED");
        result.put("lastEventAt", lastSeen == null ? null : lastSeen.toString());
        result.put("queueLength", 0);
        result.put("players", players);
        return result;
    }

    private List<Map<String, Object>> players(String sessionId) {
        List<Map<String, Object>> rows = jdbc.queryForList("""
                SELECT p.id, p.member_id AS memberId, p.participant_index AS participantIndex,
                       m.name AS memberName
                  FROM game_play_records p JOIN members m ON m.id=p.member_id
                 WHERE p.external_session_id=? AND p.status='RUNNING'
                 ORDER BY p.participant_index, p.id
                """, sessionId);
        List<Map<String, Object>> result = new ArrayList<>();
        for (Map<String, Object> row : rows) {
            String name = protectedData.decryptField("members", "name", row.get("memberName"));
            LinkedHashMap<String, Object> player = new LinkedHashMap<>();
            player.put("id", row.get("memberId"));
            player.put("memberId", row.get("memberId"));
            player.put("name", name);
            player.put("playerIndex", row.get("participantIndex"));
            // Legacy callbacks carry no live score, so do not fabricate one.
            result.add(player);
        }
        return result;
    }

}
package com.ledgame.platform;

import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

@Service
public class RoomSettingsService {
    private static final Pattern IPV4 = Pattern.compile("\\d{1,3}(?:\\.\\d{1,3}){3}");
    private final JdbcTemplate jdbc;

    public RoomSettingsService(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Map<String, Object>> merge(List<Map<String, Object>> projections) {
        Map<String, Map<String, Object>> merged = new LinkedHashMap<>();
        for (Map<String, Object> projection : projections) {
            String ip = RoomConnectionRegistry.normalizeIp(String.valueOf(projection.get("ip")));
            merged.put(ip, withName(projection, ip));
        }
        for (Map<String, Object> setting : jdbc.queryForList(
                "SELECT room_ip AS ip, display_name AS roomName FROM room_settings ORDER BY room_ip")) {
            String ip = RoomConnectionRegistry.normalizeIp(String.valueOf(setting.get("ip")));
            if (!merged.containsKey(ip)) merged.put(ip, offlineProjection(ip, String.valueOf(setting.get("roomName"))));
        }
        return new ArrayList<>(merged.values());
    }

    public Map<String, Object> saveName(String rawIp, String rawName) {
        String ip = validateIp(rawIp);
        String name = rawName == null ? "" : rawName.trim();
        if (name.isBlank() || name.length() > 40) {
            throw new PlatformApiException(HttpStatus.BAD_REQUEST, "ROOM_NAME_INVALID",
                    "Room name must contain 1 to 40 characters");
        }
        String now = Instant.now().toString();
        jdbc.update("""
                INSERT INTO room_settings(room_ip, display_name, created_at, updated_at)
                VALUES (?, ?, ?, ?)
                ON CONFLICT(room_ip) DO UPDATE SET display_name=excluded.display_name, updated_at=excluded.updated_at
                """, ip, name, now, now);
        return Map.of("ip", ip, "roomName", name, "updatedAt", now);
    }

    public String validateIp(String rawIp) {
        String ip = RoomConnectionRegistry.normalizeIp(rawIp);
        if (ip.isBlank() || ip.length() > 45 || (!IPV4.matcher(ip).matches() && !ip.contains(":"))) {
            throw new PlatformApiException(HttpStatus.BAD_REQUEST, "ROOM_IP_INVALID", "Invalid room IP");
        }
        if (IPV4.matcher(ip).matches()) {
            for (String part : ip.split("\\.")) {
                if (Integer.parseInt(part) > 255) {
                    throw new PlatformApiException(HttpStatus.BAD_REQUEST, "ROOM_IP_INVALID", "Invalid room IP");
                }
            }
        }
        return ip;
    }

    private Map<String, Object> withName(Map<String, Object> source, String ip) {
        Map<String, Object> result = new LinkedHashMap<>(source);
        String current = String.valueOf(result.getOrDefault("roomName", "")).trim();
        Map<String, Object> setting = findSetting(ip);
        result.put("roomName", setting == null ? (current.isBlank() ? ip : current) : setting.get("roomName"));
        return result;
    }

    private Map<String, Object> findSetting(String ip) {
        List<Map<String, Object>> rows = jdbc.queryForList(
                "SELECT display_name AS roomName FROM room_settings WHERE room_ip = ?", ip);
        return rows.isEmpty() ? null : rows.get(0);
    }

    private static Map<String, Object> offlineProjection(String ip, String name) {
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("ip", ip);
        result.put("deviceId", "");
        result.put("roomId", "");
        result.put("roomName", name);
        result.put("connectionId", "");
        result.put("online", false);
        result.put("state", Map.of());
        result.put("lastSequence", -1L);
        result.put("lastEventType", null);
        result.put("lastEventAt", null);
        result.put("queueLength", 0);
        result.put("players", List.of());
        return result;
    }
}
package com.ledgame.platform;

import java.util.List;
import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.RequestHeader;

@RestController
@RequestMapping("/api/rooms")
@CrossOrigin(origins = "*")
public class RoomController {
    private final RoomConnectionRegistry registry;
    private final LegacyRoomPresenceService legacyRooms;
    private final RoomSettingsService settings;
    private final OperatorAuthorizationService authorization;

    public RoomController(RoomConnectionRegistry registry, LegacyRoomPresenceService legacyRooms, RoomSettingsService settings,
            OperatorAuthorizationService authorization) {
        this.registry = registry;
        this.legacyRooms = legacyRooms;
        this.settings = settings;
        this.authorization = authorization;
    }

    @GetMapping
    public List<Map<String, Object>> list(@RequestHeader(value = "X-Operator-Id", required = false) Long operatorId) {
        authorization.requireCapability(operatorId, OperatorCapability.OPERATIONS_VIEW);
        java.util.LinkedHashMap<String, Map<String, Object>> projections = new java.util.LinkedHashMap<>();
        registry.list().forEach(room -> projections.put(String.valueOf(room.get("ip")), room));
        legacyRooms.list().forEach(room -> projections.putIfAbsent(String.valueOf(room.get("ip")), room));
        return settings.merge(List.copyOf(projections.values()));
    }

    @GetMapping("/{ip}")
    public Map<String, Object> get(@PathVariable String ip,
            @RequestHeader(value = "X-Operator-Id", required = false) Long operatorId) {
        authorization.requireCapability(operatorId, OperatorCapability.OPERATIONS_VIEW);
        Map<String, Object> projection = registry.find(ip);
        if (projection == null) projection = legacyRooms.find(ip);
        Map<String, Object> room = projection == null
                ? settings.merge(List.of()).stream()
                        .filter(item -> item.get("ip").equals(RoomConnectionRegistry.normalizeIp(ip)))
                        .findFirst().orElse(null)
                : settings.merge(List.of(projection)).get(0);
        if (room == null) throw new RoomNotFoundException();
        return room;
    }

    @PutMapping("/{ip}")
    public Map<String, Object> rename(@PathVariable String ip, @RequestBody RoomNameRequest request,
            @RequestHeader(value = "X-Operator-Id", required = false) Long operatorId) {
        authorization.requireCapability(operatorId, OperatorCapability.OPERATIONS_VIEW);
        settings.saveName(ip, request == null ? null : request.roomName());
        return get(ip, operatorId);
    }

    public record RoomNameRequest(String roomName) {}

    @ResponseStatus(HttpStatus.NOT_FOUND)
    private static final class RoomNotFoundException extends RuntimeException {}
}
