    public boolean isWristband(GameLaunchOptions options) {
        return options != null && "wristband".equalsIgnoreCase(options.launchMethod());
    }

    /**
     * Validates the complete token snapshot and activates only tokens appended to
     * the already accepted prefix. Callers may invoke this before publishing a
     * preparation revision so a rejected card cannot corrupt the visible draft.
     */
    public synchronized void activate(GamePreparationSession session) {
        if (!isWristband(session.options())) return;
        List<String> requestedUids = wristbandUids(session.options());
        if (requestedUids.isEmpty()) return;
        int requestedCount = requiredCount(session.options());
        if (requestedUids.size() > requestedCount) {
            throw new MemberPlatformException(
                    "WRISTBAND_PARTICIPANT_LIMIT",
                    "刷卡人数已经达到本局所选人数",
                    409);
        }

        SessionAccessGroup group = sessions.computeIfAbsent(
                session.sessionId(), id -> new SessionAccessGroup(id, requestedCount));
        if (!group.participants.isEmpty() && group.userCount != requestedCount) {
            throw new MemberPlatformException(
                    "WRISTBAND_USER_COUNT_LOCKED",
                    "第一位玩家刷卡后不能修改游戏人数",
                    409);
        }
        assertAcceptedPrefix(group, requestedUids);

        for (int index = group.participants.size(); index < requestedUids.size(); index++) {
            String uid = requestedUids.get(index);
            if (group.uids().contains(uid)) {
                throw new MemberPlatformException(
                        "DUPLICATE_WRISTBAND",
                        "同一只手环不能在一局中重复刷卡",
                        409);
            }
            ActivateResponse response = client.activate(uid);
            Long memberId = response == null || response.member() == null
                    ? null
                    : response.member().id();
            if (memberId == null) {
                throw new MemberPlatformException(
                        "PLATFORM_ACCESS_INVALID",
                        "会员平台没有返回有效会员身份",
                        502);
            }
            if (group.memberIds().contains(memberId)) {
                throw new MemberPlatformException(
                        "DUPLICATE_MEMBER",
                        "同一会员不能在一局中重复参与",
                        409);
            }
            group.participants.add(new SessionParticipant(uid, response));
        }
    }

    public void validateQueuedUid(String uid) {
        String normalized = normalizeUid(uid);
        Map<String, Object> snapshot = client.inspect(normalized);
        String status = String.valueOf(snapshot.getOrDefault("status", ""));
        Object memberId = snapshot.get("memberId");
        Number remaining = snapshot.get("remainingSeconds") instanceof Number number ? number : null;
        if (!("READY".equals(status) || "ACTIVE".equals(status)) || memberId == null) {
            String actualStatus = status.isBlank() ? "NOT_FOUND" : status;
            throw new MemberPlatformException(
                    "WRISTBAND_NOT_READY",
                    "Queue requires a member-bound READY or ACTIVE wristband; current status=" + actualStatus,
                    409);
        }
        if (remaining != null && remaining.longValue() <= 0L) {
            throw new MemberPlatformException("WRISTBAND_EXPIRED", "手环可用时间已用完", 409);
        }
        if (snapshot.get("memberStatus") != null
                && !"ACTIVE".equals(String.valueOf(snapshot.get("memberStatus")))) {
            throw new MemberPlatformException("MEMBER_FROZEN", "会员已被冻结", 409);
        }
    }

    /** Starts all participant plays atomically on the platform and returns the first for legacy callers. */
    public synchronized PlayRecord startPlay(GamePreparationSession session, Game game) {
        SessionAccessGroup group = sessions.get(session.sessionId());
        if (group == null) {
            if (!isWristband(session.options())) return null;
            throw scanRequired(session.options(), 0);
        }
        int required = requiredCount(session.options());
        if (group.participants.size() != required) {
            throw scanRequired(session.options(), group.participants.size());
        }
        if (group.participants.stream().allMatch(participant -> participant.play != null)) {
            return group.participants.get(0).play;
        }

        List<PlayRecord> plays;
        List<String> uids = group.uids();
        if (uids.size() == 1) {
            plays = List.of(client.startPlay(
                    uids.get(0), session.sessionId(), String.valueOf(game.getId()), game.getName()));
        } else {
            plays = client.startPlays(
                    uids, session.sessionId(), String.valueOf(game.getId()), game.getName());
        }
        if (plays == null || plays.size() != group.participants.size()) {
            throw new MemberPlatformException(
                    "PLATFORM_PLAY_BATCH_INVALID",
                    "会员平台返回的多人游戏记录数量不正确",
                    502);
        }
        for (int index = 0; index < plays.size(); index++) {
            PlayRecord play = plays.get(index);
            SessionParticipant participant = group.participants.get(index);
            if (play == null || !participant.uid.equals(play.uid())) {
                throw new MemberPlatformException(
                        "PLATFORM_PLAY_BATCH_INVALID",
                        "会员平台返回的多人游戏记录顺序不正确",
                        502);
            }
        }
        for (int index = 0; index < plays.size(); index++) {
            group.participants.get(index).play = plays.get(index);
        }
        return plays.get(0);
    }

    public void attachContext(String sessionId, GameContext context) {
        if (sessions.containsKey(sessionId)) contexts.put(context, sessionId);
    }

    public void cancel(String sessionId) {
        sessions.remove(sessionId);
        releaseContexts(sessionId);
    }

    public void startupAbort(String sessionId, Throwable error) {
        SessionAccessGroup group = sessions.get(sessionId);
        if (group == null) return;
        reportAll(group, new PlayResultRequest(false, "STARTUP_ABORT", null,
                Map.of("error", error == null ? "startup aborted" : String.valueOf(error.getMessage()))));
        sessions.remove(sessionId);
        releaseContexts(sessionId);
    }

    public void natural(GameContext context, boolean success) {
        SessionAccessGroup group = groupFor(context);
        if (group == null) return;
        reportAll(group, participantIndex -> {
            GameResult result = result(context, participantIndex);
            return new PlayResultRequest(
                    success,
                    success ? "NATURAL_COMPLETION" : "NATURAL_FAILURE",
                    result.score(),
                    result.payload(),
                    scoringInput(context, participantIndex, true));
        });
        releaseSession(context, group);
    }

    public void stopped(GameContext context) {
        stopped(context, GameEngine.getLastTermination());
    }

    void stopped(GameContext context, GameTermination termination) {
        SessionAccessGroup group = groupFor(context);
        if (group == null) return;
        String reason = termination == null ? "RUNTIME_ERROR" : termination.reason().name();
        reportAll(group, participantIndex -> {
            GameResult result = result(context, participantIndex);
            return new PlayResultRequest(
                    termination == null ? null : termination.success(),
                    reason,
                    result.score(),
                    result.payload(),
                    scoringInput(context, participantIndex, false));
        });
        releaseSession(context, group);
    }

    private void releaseSession(GameContext context, SessionAccessGroup group) {
        contexts.remove(context);
        sessions.remove(group.sessionId);
    }

    private void releaseContexts(String sessionId) {
        contexts.values().removeIf(sessionId::equals);
    }

    int retainedSessionCount() {
        return sessions.size();
    }

    int retainedContextCount() {
        return contexts.size();
    }

