    private void reportAll(SessionAccessGroup group, PlayResultRequest result) {
        reportAll(group, participantIndex -> result);
    }

    private void reportAll(SessionAccessGroup group, IntFunction<PlayResultRequest> resultFactory) {
        for (int participantIndex = 0; participantIndex < group.participants.size(); participantIndex++) {
            SessionParticipant participant = group.participants.get(participantIndex);
            try {
                report(group.sessionId, participant, resultFactory.apply(participantIndex));
            } catch (RuntimeException exception) {
                log.error("member platform result capture failed but remaining participants will continue: " +
                                "sessionId={}, playId={}, code={}",
                        group.sessionId,
                        participant.play == null ? null : participant.play.id(),
                        exception instanceof MemberPlatformException platform
                                ? platform.getCode()
