        try {
            if (settlementOutbox == null) {
                participant.play = client.reportResult(participant.play.id(), result);
            } else {
                settlementOutbox.captureAndTry(participant.play.id(), result);
            }
        } catch (RuntimeException exception) {
            participant.settlementClaimed.set(false);
