        @Override
        public CompletionStage<?> onClose(WebSocket webSocket, int statusCode, String reason) {
            if (socket == webSocket) {
                socket = null;
                ScheduledFuture<?> currentPing = pingTask;
                pingTask = null;
                if (currentPing != null) currentPing.cancel(false);
            }
            scheduleReconnect();
            return null;
        }

        @Override
        public void onError(WebSocket webSocket, Throwable error) {
            if (socket == webSocket) {
                socket = null;
                ScheduledFuture<?> currentPing = pingTask;
                pingTask = null;
                if (currentPing != null) currentPing.cancel(false);
            }
            log.warn("room connection failed: {}", error.getMessage());
            scheduleReconnect();
        }
    }
