import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class SettlementOutboxService {
    private static final Logger log = LoggerFactory.getLogger(SettlementOutboxService.class);

    private final JdbcTemplate jdbc;
    private final ObjectMapper objectMapper;
    private final MemberPlatformClient client;
    private final MemberPlatformProperties properties;
    private final TransactionTemplate transactions;
    private final Object deliveryLock = new Object();

    public SettlementOutboxService(JdbcTemplate jdbc, ObjectMapper objectMapper,
            MemberPlatformClient client, MemberPlatformProperties properties,
            TransactionTemplate transactions) {
        this.jdbc = jdbc;
        this.objectMapper = objectMapper;
        this.client = client;
        this.properties = properties;
        this.transactions = transactions;
    }

    public void captureAndTry(long platformPlayId, PlayResultRequest result) {
        capture(platformPlayId, result);
        deliver(platformPlayId, Instant.now());
    }

    public void capture(long platformPlayId, PlayResultRequest result) {
        String payload = serialize(result);
        Instant now = Instant.now();
        transactions.executeWithoutResult(status -> insertIfAbsent(platformPlayId, payload, now));
    }

    private void insertIfAbsent(long platformPlayId, String payload, Instant now) {
        try {
            jdbc.update("""
                INSERT INTO game_settlement_outbox(
                    platform_play_id, payload_json, state, attempt_count,
                    next_attempt_at, created_at, updated_at)
                VALUES (?, ?, 'PENDING', 0, ?, ?, ?)
                """, platformPlayId, payload, timestamp(now), timestamp(now), timestamp(now));
        } catch (DataIntegrityViolationException duplicate) {
            // The first payload for a platform play is immutable and remains authoritative.
            if (jdbc.queryForObject(
                    "SELECT COUNT(*) FROM game_settlement_outbox WHERE platform_play_id=?",
                    Integer.class, platformPlayId) == 0) {
                throw duplicate;
            }
        }
    }

    @Scheduled(fixedDelayString = "#{@memberPlatformProperties.settlementPollInterval.toMillis()}")
    public void deliverDue() {
        deliverDue(Instant.now());
    }

    void deliverDue(Instant now) {
        List<Long> due = jdbc.queryForList("""
            SELECT platform_play_id
              FROM game_settlement_outbox
             WHERE state='PENDING' AND (next_attempt_at IS NULL OR next_attempt_at<=?)
             ORDER BY id
             LIMIT 50
            """, Long.class, timestamp(now));
        for (Long platformPlayId : due) deliver(platformPlayId, now);
    }

    @EventListener(ApplicationReadyEvent.class)
    public void recoverPendingOnStartup() {
        deliverDue();
    }

