    private static GameResult result(GameContext context, int participantIndex) {
        Object gameplay = context == null ? null : context.getGameplayState();
        if (gameplay instanceof SimpleGameplayState simple) {
            Map<String, Object> snapshot = simple.snapshot().toMap();
            return new GameResult(simple.snapshot().score(), snapshot);
        }
        if (gameplay instanceof RankType1GameplayState rank) {
            int score = rank.scoreFor(participantIndex);
            LinkedHashMap<String, Object> payload = new LinkedHashMap<>(rank.gameplaySnapshot());
            payload.put("participantIndex", participantIndex);
            payload.put("score", score);
            return new GameResult(score, payload);
        }
        LinkedHashMap<String, Object> payload = new LinkedHashMap<>();
        payload.put("gameplayStateType", gameplay == null ? null : gameplay.getClass().getName());
        return new GameResult(null, payload);
    }

    private static GameScoringInput scoringInput(GameContext context, int participantIndex, boolean eligible) {
        ParticipantAwardLedger.ScoringSnapshot snapshot = context.getAwardLedger().snapshot(participantIndex, eligible);
        return new GameScoringInput("level-clear-points-v1", snapshot.awardEligible(), snapshot.totalPoints(),
                snapshot.levels().stream().map(level -> new LevelAward(level.levelIndex(),
                        level.rewardPoints(), level.awardedPoints(), level.reason())).toList());
    }

