        private SessionAccessGroup(String sessionId, int userCount) {
            this.sessionId = sessionId;
            this.userCount = userCount;
        }

        private List<String> uids() {
            return participants.stream().map(participant -> participant.uid).toList();
        }

        private Set<Long> memberIds() {
            Set<Long> ids = new LinkedHashSet<>();
            for (SessionParticipant participant : participants) {
                if (participant.activation.member() != null) {
                    ids.add(participant.activation.member().id());
                }
            }
            return ids;
        }
    }

