package com.ledgame.service;

import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import com.ledgame.entity.GameCategory;
import com.ledgame.mapper.GameCategoryMapper;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;

@Service
public class GameCategoryService extends ServiceImpl<GameCategoryMapper, GameCategory> {

    public List<GameCategory> listOrdered() {
        return list().stream()
                .sorted(Comparator.comparing(GameCategory::getDisplayOrder,
                                Comparator.nullsLast(Integer::compareTo))
                        .thenComparing(GameCategory::getId, Comparator.nullsLast(Long::compareTo)))
                .toList();
    }

    @Transactional
    public GameCategory create(GameCategory request) {
        String name = normalizeName(request == null ? null : request.getName());
        ensureUniqueName(name, null);
        GameCategory category = new GameCategory();
        category.setName(name);
        category.setCover(normalizeCover(request == null ? null : request.getCover()));
        category.setDisplayOrder(nextDisplayOrder());
        save(category);
        return category;
    }

    @Transactional
    public GameCategory update(Long id, GameCategory request) {
        if (id == null) throw new IllegalArgumentException("游戏分类 ID 不能为空");
        GameCategory category = getById(id);
        if (category == null) throw new IllegalArgumentException("游戏分类不存在: " + id);
        if (request == null) throw new IllegalArgumentException("游戏分类内容不能为空");
        String name = normalizeName(request.getName());
        ensureUniqueName(name, id);
        category.setName(name);
        category.setCover(normalizeCover(request.getCover()));
        updateById(category);
        return category;
    }

    private int nextDisplayOrder() {
        return list().stream()
                .map(GameCategory::getDisplayOrder)
                .filter(order -> order != null)
                .max(Integer::compareTo)
                .orElse(-1) + 1;
    }

    private void ensureUniqueName(String name, Long currentId) {
        boolean duplicate = list().stream().anyMatch(item ->
                !Objects.equals(item.getId(), currentId)
                        && item.getName() != null
                        && item.getName().trim().equalsIgnoreCase(name));
        if (duplicate) throw new IllegalArgumentException("游戏分类名称已存在: " + name);
    }

    private String normalizeName(String value) {
        if (!StringUtils.hasText(value)) throw new IllegalArgumentException("游戏分类名称不能为空");
        String name = value.trim();
        if (name.length() > 255) throw new IllegalArgumentException("游戏分类名称不能超过 255 个字符");
        return name;
    }

    private String normalizeCover(String value) {
        if (value == null) return null;
        String cover = value.trim();
        if (cover.length() > 255) throw new IllegalArgumentException("游戏分类封面路径不能超过 255 个字符");
        return cover.isEmpty() ? null : cover;
    }
}
