+            // Only update order: do not overwrite a concurrent name/cover edit.
+            GameCategory patch = new GameCategory();
+            patch.setId(categoryIds.get(index));
+            patch.setDisplayOrder(index);
+            if (!updateById(patch)) throw new IllegalStateException("保存分类排序失败，请刷新后重试");
