class GameCategoryServiceTest {
    @Test
    void createsCategoryAfterTheCurrentMaximumOrder() {
        GameCategoryService service = spy(new GameCategoryService());
        GameCategory existing = category(3L, "Existing", 4);
        doReturn(List.of(existing)).when(service).list();
        doReturn(true).when(service).save(any(GameCategory.class));

        GameCategory request = category(null, "  Family  ", null);
