package com.ledgame.service;

import static org.assertj.core.api.Assertions.assertThat;

import com.ledgame.entity.Spirit;
import com.ledgame.dto.SpiritCreateReq;
import java.util.Date;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.TestPropertySource;

@SpringBootTest
@TestPropertySource(properties = "led.bridge.enabled=false")
class SpiritServicePersistenceTest {

    @Autowired
    private SpiritService spiritService;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Test
    void savesAndReadsLegacySpiritFields() {
        Spirit spirit = new Spirit();
        spirit.setId("legacy-spirit-1");
        spirit.setName("Legacy spirit");
        spirit.setColor(3);
        spirit.setWidth(5);
        spirit.setHeight(6);
        spirit.setPoints("0,0;1,0;1,1");
        spirit.setBasic(false);
        spirit.setCreateTime(new Date(1_000L));
        spirit.setUpdateTime(new Date(2_000L));

        assertThat(spiritService.save(spirit)).isTrue();

        Spirit saved = spiritService.getById("legacy-spirit-1");
        assertThat(saved.getName()).isEqualTo("Legacy spirit");
        assertThat(saved.getColor()).isEqualTo(3);
        assertThat(saved.getWidth()).isEqualTo(5);
        assertThat(saved.getHeight()).isEqualTo(6);
        assertThat(saved.getPoints()).isEqualTo("0,0;1,0;1,1");
        assertThat(saved.getBasic()).isFalse();
    }

    @Test
    void simpleListKeepsDisplayFields() {
        Spirit spirit = new Spirit();
        spirit.setId("legacy-spirit-2");
        spirit.setName("Summary spirit");
        spirit.setColor(4);
        spirit.setWidth(2);
        spirit.setHeight(3);
        spirit.setPoints("0,0");
        spirit.setBasic(true);

        assertThat(spiritService.save(spirit)).isTrue();

        assertThat(spiritService.listSimpleSpirits())
                .anySatisfy(resp -> {
                    assertThat(resp.getId()).isEqualTo("legacy-spirit-2");
                    assertThat(resp.getName()).isEqualTo("Summary spirit");
                    assertThat(resp.getColor()).isEqualTo(4);
                    assertThat(resp.getWidth()).isEqualTo(2);
                    assertThat(resp.getHeight()).isEqualTo(3);
                    assertThat(resp.getPoints()).isEqualTo("0,0");
                    assertThat(resp.getBasic()).isTrue();
                });
    }

    @Test
    void schemaContainsSpiritColumns() {
        List<String> columns = jdbcTemplate.queryForList("""
                SELECT LOWER(COLUMN_NAME)
                FROM INFORMATION_SCHEMA.COLUMNS
                WHERE TABLE_NAME = 'spirit'
                """, String.class);

        assertThat(columns).contains(
                "id",
                "name",
                "color",
                "width",
                "height",
                "points",
                "basic",
                "create_time",
                "update_time");
    }

    @Test
    void pointsColumnSupportsDenseJsonBeyondLegacyLimit() {
        Spirit spirit = new Spirit();
        spirit.setId("dense-spirit");
        spirit.setName("Dense spirit");
        spirit.setWidth(32);
        spirit.setHeight(32);
        spirit.setPoints("[" + "[0,0],".repeat(300) + "[0,0]]");

        assertThat(spirit.getPoints()).hasSizeGreaterThan(1024);
        assertThat(spiritService.save(spirit)).isTrue();
        assertThat(spiritService.getById("dense-spirit").getPoints()).isEqualTo(spirit.getPoints());
    }

    @Test
    void createsAndReadsCustomSpirit() {
        Spirit created = spiritService.createSpirit(new SpiritCreateReq(
                "Created spirit", 3, 2, List.of(List.of(0, 0), List.of(2, 1))));

        assertThat(created.getId()).hasSize(36);
        assertThat(created.getColor()).isZero();
        assertThat(created.getBasic()).isFalse();
        Spirit persisted = spiritService.getById(created.getId());
        assertThat(persisted.getName()).isEqualTo("Created spirit");
        assertThat(persisted.getPoints()).isEqualTo("[[0,0],[2,1]]");
    }
}

export function createOrderDraft(games) {
  return [...games];
}

export function moveOrderItem(games, index, delta) {
  const target = index + delta;
  if (index < 0 || index >= games.length || target < 0 || target >= games.length) return [...games];
  const next = [...games];
  [next[index], next[target]] = [next[target], next[index]];
  return next;
}

export function orderedGameIds(games) {
  return games.map((game) => Number(game.id));
}
export const MAX_SPIRIT_DIMENSION = 96;

export function clampSpiritDimension(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) {
    return 1;
  }
  return Math.min(MAX_SPIRIT_DIMENSION, Math.max(1, Math.floor(number)));
}

export function parseSpiritPoints(value) {
  let points = value;
  if (typeof value === "string") {
    try {
      points = JSON.parse(value);
    } catch (_error) {
      return [];
    }
  }
  if (!Array.isArray(points)) {
    return [];
  }
  const unique = new Map();
  for (const point of points) {
    if (!Array.isArray(point) || point.length < 2) {
      continue;
    }
    const x = Number(point[0]);
    const y = Number(point[1]);
    if (Number.isInteger(x) && Number.isInteger(y)) {
      unique.set(`${x}:${y}`, [x, y]);
    }
  }
  return [...unique.values()];
}

export function cropSpiritPoints(points, width, height) {
  const safeWidth = clampSpiritDimension(width);
  const safeHeight = clampSpiritDimension(height);
  return parseSpiritPoints(points)
    .filter(([x, y]) => x >= 0 && x < safeWidth && y >= 0 && y < safeHeight)
    .sort(([leftX, leftY], [rightX, rightY]) => leftY - rightY || leftX - rightX);
}

export function createSpiritUpdatePayload(width, height, points) {
  const safeWidth = clampSpiritDimension(width);
  const safeHeight = clampSpiritDimension(height);
  return {
    width: safeWidth,
    height: safeHeight,
    points: cropSpiritPoints(points, safeWidth, safeHeight),
  };
}

export function createSpiritCreatePayload(name, width, height, points) {
  return {
    name: String(name || "").trim(),
    ...createSpiritUpdatePayload(width, height, points),
  };
}
<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useI18n } from "vue-i18n";
import {
  MAX_SPIRIT_DIMENSION,
  clampSpiritDimension,
  createSpiritCreatePayload,
  createSpiritUpdatePayload,
  cropSpiritPoints,
  parseSpiritPoints,
} from "../lib/spiritPoints.js";

const props = defineProps({
  spirit: { type: Object, required: true },
  creating: { type: Boolean, default: false },
  saving: { type: Boolean, default: false },
  error: { type: String, default: "" },
});
const emit = defineEmits(["cancel", "save"]);
const { t } = useI18n();

const dialogRef = ref(null);
const canvasRef = ref(null);
const stageRef = ref(null);
const width = ref(1);
const height = ref(1);
const name = ref("");
const pointKeys = ref(new Set());
const stageSize = ref({ width: 0, height: 0 });
let resizeObserver = null;
let pointerId = null;
let paintMode = "on";
let lastPaintKey = "";

const pointCount = computed(() => pointKeys.value.size);
const canSave = computed(() => !props.saving && (!props.creating || name.value.trim().length > 0));

function resetDraft() {
  name.value = props.spirit?.name || "";
  width.value = clampSpiritDimension(props.spirit?.width);
  height.value = clampSpiritDimension(props.spirit?.height);
  const points = cropSpiritPoints(parseSpiritPoints(props.spirit?.points), width.value, height.value);
  pointKeys.value = new Set(points.map(([x, y]) => `${x}:${y}`));
  nextTick(drawCanvas);
}

function applyDimensionChange() {
  width.value = clampSpiritDimension(width.value);
  height.value = clampSpiritDimension(height.value);
  const cropped = [...pointKeys.value]
    .map((key) => key.split(":").map(Number))
    .filter(([x, y]) => x >= 0 && x < width.value && y >= 0 && y < height.value);
  pointKeys.value = new Set(cropped.map(([x, y]) => `${x}:${y}`));
  drawCanvas();
}

function canvasMetrics() {
  const availableWidth = Math.max(1, stageSize.value.width);
  const availableHeight = Math.max(1, stageSize.value.height);
  const cell = Math.max(1, Math.floor(Math.min(availableWidth / width.value, availableHeight / height.value)));
  return {
    cell,
    width: cell * width.value,
    height: cell * height.value,
  };
}

function drawCanvas() {
  const canvas = canvasRef.value;
  if (!canvas) {
    return;
  }
  const metrics = canvasMetrics();
  const dpr = Math.max(1, window.devicePixelRatio || 1);
  canvas.style.width = `${metrics.width}px`;
  canvas.style.height = `${metrics.height}px`;
  canvas.width = Math.max(1, Math.round(metrics.width * dpr));
  canvas.height = Math.max(1, Math.round(metrics.height * dpr));
  const context = canvas.getContext("2d");
  context.setTransform(dpr, 0, 0, dpr, 0, 0);
  context.imageSmoothingEnabled = false;
  context.fillStyle = "#070a0f";
  context.fillRect(0, 0, metrics.width, metrics.height);
  for (let y = 0; y < height.value; y += 1) {
    for (let x = 0; x < width.value; x += 1) {
      if (pointKeys.value.has(`${x}:${y}`)) {
        context.fillStyle = "#4f8fce";
        context.fillRect(x * metrics.cell, y * metrics.cell, metrics.cell, metrics.cell);
      }
      context.strokeStyle = "rgba(180, 204, 230, 0.34)";
      context.lineWidth = 1;
      context.strokeRect(x * metrics.cell + 0.5, y * metrics.cell + 0.5, metrics.cell - 1, metrics.cell - 1);
    }
  }
}

function pointFromEvent(event) {
  const canvas = canvasRef.value;
  if (!canvas) {
    return null;
  }
  const rect = canvas.getBoundingClientRect();
  const x = Math.floor(((event.clientX - rect.left) / rect.width) * width.value);
  const y = Math.floor(((event.clientY - rect.top) / rect.height) * height.value);
  if (x < 0 || x >= width.value || y < 0 || y >= height.value) {
    return null;
  }
  return { x, y, key: `${x}:${y}` };
}

function paintPoint(event) {
  const point = pointFromEvent(event);
  if (!point || point.key === lastPaintKey) {
    return;
  }
  lastPaintKey = point.key;
  const next = new Set(pointKeys.value);
  if (paintMode === "on") {
    next.add(point.key);
  } else {
    next.delete(point.key);
  }
  pointKeys.value = next;
  drawCanvas();
}

function handlePointerDown(event) {
  if (props.saving || event.button !== 0) {
    return;
  }
  const point = pointFromEvent(event);
  if (!point) {
    return;
  }
  event.preventDefault();
  pointerId = event.pointerId;
  paintMode = pointKeys.value.has(point.key) ? "off" : "on";
  lastPaintKey = "";
  canvasRef.value.setPointerCapture(event.pointerId);
  paintPoint(event);
}

function handlePointerMove(event) {
  if (pointerId !== event.pointerId) {
    return;
  }
  paintPoint(event);
}

function handlePointerUp(event) {
  if (pointerId !== event.pointerId) {
    return;
  }
  if (canvasRef.value?.hasPointerCapture(event.pointerId)) {
    canvasRef.value.releasePointerCapture(event.pointerId);
  }
  pointerId = null;
  lastPaintKey = "";
}

function handleSave() {
  const points = [...pointKeys.value].map((key) => key.split(":").map(Number));
  emit(
    "save",
    props.creating
      ? createSpiritCreatePayload(name.value, width.value, height.value, points)
      : createSpiritUpdatePayload(width.value, height.value, points),
  );
}

function handleKeydown(event) {
  if (event.key === "Escape" && !props.saving) {
    emit("cancel");
    return;
  }
  if (event.key !== "Tab") {
    return;
  }
  const focusable = [...(dialogRef.value?.querySelectorAll("button:not(:disabled), input:not(:disabled)") || [])];
  if (!focusable.length) {
    event.preventDefault();
    dialogRef.value?.focus();
    return;
  }
  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if (event.shiftKey && document.activeElement === first) {
    event.preventDefault();
    last.focus();
  } else if (!event.shiftKey && document.activeElement === last) {
    event.preventDefault();
    first.focus();
  }
}

watch(() => props.spirit, resetDraft, { immediate: true });
watch([width, height], applyDimensionChange);

onMounted(() => {
  resizeObserver = new ResizeObserver(([entry]) => {
    stageSize.value = { width: entry.contentRect.width, height: entry.contentRect.height };
    drawCanvas();
  });
  if (stageRef.value) {
    resizeObserver.observe(stageRef.value);
  }
  window.addEventListener("keydown", handleKeydown);
  nextTick(() => dialogRef.value?.focus());
});

onBeforeUnmount(() => {
  resizeObserver?.disconnect();
  window.removeEventListener("keydown", handleKeydown);
});
</script>

<template>
  <div class="spirit-editor-backdrop" @mousedown.self="!saving && emit('cancel')">
    <section
      ref="dialogRef"
      class="spirit-editor-dialog"
      :class="{ creating }"
      role="dialog"
      aria-modal="true"
      aria-labelledby="spirit-editor-title"
      tabindex="-1"
    >
      <header class="spirit-editor-header">
        <div>
          <h2 id="spirit-editor-title">{{ creating
            ? t("spiritEditor.create")
            : t("spiritEditor.edit", { name: spirit.name || spirit.id })
          }}</h2>
          <p>{{ t("spiritEditor.pointCount", { count: pointCount }) }}</p>
        </div>
        <button class="inline-symbol-button" type="button" :title="t('common.close')" :disabled="saving" @click="emit('cancel')">×</button>
      </header>

      <label v-if="creating" class="spirit-editor-name">
        {{ t("spiritEditor.name") }}
        <input v-model="name" type="text" maxlength="255" :disabled="saving" autofocus />
      </label>

      <div class="spirit-editor-size-controls">
        <label>{{ t("spiritEditor.width") }} <input v-model.number="width" type="number" min="1" :max="MAX_SPIRIT_DIMENSION" :disabled="saving" /></label>
        <label>{{ t("spiritEditor.height") }} <input v-model.number="height" type="number" min="1" :max="MAX_SPIRIT_DIMENSION" :disabled="saving" /></label>
        <span>{{ width }} × {{ height }}</span>
      </div>

      <div ref="stageRef" class="spirit-editor-stage">
        <canvas
          ref="canvasRef"
          class="spirit-editor-canvas"
          :aria-label="t('spiritEditor.canvasLabel')"
          @pointerdown="handlePointerDown"
          @pointermove="handlePointerMove"
          @pointerup="handlePointerUp"
          @pointercancel="handlePointerUp"
          @wheel.prevent
        ></canvas>
      </div>

      <p v-if="error" class="spirit-editor-error">{{ error }}</p>
      <footer class="spirit-editor-actions">
        <button class="soft-button" type="button" :disabled="saving" @click="emit('cancel')">{{ t("common.cancel") }}</button>
        <button class="action-button primary" type="button" :disabled="!canSave" @click="handleSave">
          {{ t(saving ? "globalConfig.saving" : "common.save") }}
        </button>
      </footer>
    </section>
  </div>
</template>
<script setup>
import { ref } from "vue";
import { useI18n } from "vue-i18n";
import { setApplicationLocale } from "../i18n/index.js";
import { APPLICATION_LANGUAGE_OPTIONS } from "../lib/applicationLanguages.js";
import { LOCALE_FLAG_URLS } from "../lib/localeFlags.js";

defineProps({
  compact: {
    type: Boolean,
    default: false,
  },
  showIntro: {
    type: Boolean,
    default: true,
  },
});

const emit = defineEmits(["selected"]);
const { locale, t } = useI18n({ useScope: "global" });
const errorMessage = ref("");
const busy = ref(false);

async function selectLanguage(value) {
  if (busy.value || value === locale.value) {
    return;
  }
  busy.value = true;
  errorMessage.value = "";
  try {
    await setApplicationLocale(value);
    emit("selected", value);
  } catch (error) {
    errorMessage.value = error?.message || t("language.saveError");
  } finally {
    busy.value = false;
  }
}
</script>

<template>
  <section
    class="language-settings language-selection-panel"
    :class="{ compact }"
    :aria-label="t('language.title')"
  >
    <div v-if="showIntro">
      <strong>{{ t("language.current") }}</strong>
      <p>{{ t("language.description") }}</p>
    </div>
    <div class="language-options" role="radiogroup" :aria-label="t('language.title')">
      <label v-for="option in APPLICATION_LANGUAGE_OPTIONS" :key="option.value" class="language-option">
        <input
          :checked="locale === option.value"
          :disabled="busy"
          :value="option.value"
          name="application-language"
          type="radio"
          @change="selectLanguage(option.value)"
        />
        <img class="language-option-flag" :src="LOCALE_FLAG_URLS[option.flagCode]" alt="" />
        <span>{{ option.label }}</span>
        <small>{{ option.value }}</small>
      </label>
    </div>
    <p v-if="errorMessage" class="error-line" role="alert">{{ errorMessage }}</p>
  </section>
</template>
