package com.ledgame.service;

import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.ledgame.common.ResourceNotFoundException;
import com.ledgame.dto.SimpleSpiritResp;
import com.ledgame.dto.SpiritCreateReq;
import com.ledgame.dto.SpiritUpdateReq;
import com.ledgame.entity.Spirit;
import com.ledgame.mapper.SpiritMapper;
import java.util.ArrayList;
import java.util.Date;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import org.springframework.beans.BeanUtils;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class SpiritService extends ServiceImpl<SpiritMapper, Spirit> {
    private static final int MAX_DIMENSION = 96;

    private final SpiritMapper spiritMapper;
    private final ObjectMapper objectMapper;

    public SpiritService(SpiritMapper spiritMapper, ObjectMapper objectMapper) {
        this.spiritMapper = spiritMapper;
        this.objectMapper = objectMapper;
    }

    public List<SimpleSpiritResp> listSimpleSpirits() {
        return list().stream()
                .map(this::toSimpleResp)
                .toList();
    }

    @Transactional
    public Spirit createSpirit(SpiritCreateReq request) {
        if (request == null) {
            throw new IllegalArgumentException("创建请求不能为空");
        }
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty() || name.length() > 255) {
            throw new IllegalArgumentException("名称长度必须在 1 到 255 之间");
        }
        int width = validateDimension("宽度", request.width());
        int height = validateDimension("高度", request.height());
        List<List<Integer>> points = validatePoints(request.points(), width, height);
        Date now = new Date();

        Spirit spirit = new Spirit();
        spirit.setId(UUID.randomUUID().toString());
        spirit.setName(name);
        spirit.setColor(0);
        spirit.setWidth(width);
        spirit.setHeight(height);
        spirit.setPoints(serializePoints(points));
        spirit.setBasic(false);
        spirit.setCreateTime(now);
        spirit.setUpdateTime(now);
        if (spiritMapper.insert(spirit) != 1) {
            throw new IllegalStateException("新增精灵失败");
        }
        return spiritMapper.selectById(spirit.getId());
    }

    @Transactional
    public Spirit updatePoints(String id, SpiritUpdateReq request) {
        if (id == null || id.isBlank()) {
            throw new IllegalArgumentException("精灵 id 不能为空");
        }
        if (request == null) {
            throw new IllegalArgumentException("更新请求不能为空");
        }

        Spirit spirit = spiritMapper.selectById(id);
        if (spirit == null) {
            throw new ResourceNotFoundException("精灵不存在: " + id);
        }

        int width = validateDimension("宽度", request.width());
        int height = validateDimension("高度", request.height());
        List<List<Integer>> points = validatePoints(request.points(), width, height);

        spirit.setWidth(width);
        spirit.setHeight(height);
        spirit.setPoints(serializePoints(points));
        spirit.setUpdateTime(new Date());
        if (spiritMapper.updateById(spirit) != 1) {
            throw new ResourceNotFoundException("精灵不存在: " + id);
        }
        return spiritMapper.selectById(id);
    }

    @Transactional
    public void deleteSpirit(String id) {
        if (id == null || id.isBlank()) {
            throw new IllegalArgumentException("精灵 id 不能为空");
        }
        if (spiritMapper.selectById(id) == null || spiritMapper.deleteById(id) != 1) {
            throw new ResourceNotFoundException("精灵不存在: " + id);
        }
    }

    private int validateDimension(String field, Integer value) {
        if (value == null || value < 1 || value > MAX_DIMENSION) {
            throw new IllegalArgumentException(field + "必须在 1 到 " + MAX_DIMENSION + " 之间");
        }
        return value;
    }

    private List<List<Integer>> validatePoints(List<List<Number>> points, int width, int height) {
        if (points == null) {
            throw new IllegalArgumentException("点位不能为空");
        }
        List<List<Integer>> normalized = new ArrayList<>(points.size());
        Set<Long> unique = new HashSet<>();
        for (int index = 0; index < points.size(); index++) {
            List<Number> point = points.get(index);
            if (point == null || point.size() != 2) {
                throw new IllegalArgumentException("点位 " + index + " 必须包含两个坐标");
            }
            int x = integerCoordinate(point.get(0), index, "x");
            int y = integerCoordinate(point.get(1), index, "y");
            if (x < 0 || x >= width || y < 0 || y >= height) {
                throw new IllegalArgumentException("点位 " + index + " 超出精灵尺寸范围");
            }
            long key = ((long) x << 32) ^ (y & 0xffffffffL);
            if (!unique.add(key)) {
                throw new IllegalArgumentException("点位 " + index + " 与已有点位重复");
            }
            normalized.add(List.of(x, y));
        }
        return normalized;
    }

    private int integerCoordinate(Number value, int pointIndex, String axis) {
        if (value == null) {
            throw new IllegalArgumentException("点位 " + pointIndex + " 的 " + axis + " 坐标不能为空");
        }
        double number = value.doubleValue();
        if (!Double.isFinite(number) || number != Math.rint(number)
                || number < Integer.MIN_VALUE || number > Integer.MAX_VALUE) {
            throw new IllegalArgumentException("点位 " + pointIndex + " 的 " + axis + " 坐标必须是整数");
        }
        return (int) number;
    }

    private String serializePoints(List<List<Integer>> points) {
        try {
            return objectMapper.writeValueAsString(points);
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("点位序列化失败", e);
        }
    }

    private SimpleSpiritResp toSimpleResp(Spirit spirit) {
        SimpleSpiritResp resp = new SimpleSpiritResp();
        BeanUtils.copyProperties(spirit, resp);
        return resp;
    }
}
package com.ledgame.controller;

