    @Test
    void updateReturnsPersistedSpirit() throws Exception {
        Spirit updated = new Spirit();
        updated.setId("spirit-1");
        updated.setWidth(3);
        updated.setHeight(2);
        updated.setPoints("[[0,0],[2,1]]");
        when(spiritService.updatePoints(
                org.mockito.ArgumentMatchers.eq("spirit-1"),
