    @Test void categoryOrderIsAtomicAndPreservesMetadata() throws Exception {
        categories.remove(new com.baomidou.mybatisplus.core.conditions.query.QueryWrapper<>());
        GameCategory a = createCategory("UI A", "a.png");
        GameCategory b = createCategory("UI B", "b.png");
        List<Long> original = List.of(a.getId(), b.getId());
        for (List<Long> invalid : Arrays.asList(List.of(a.getId()), List.of(a.getId(), a.getId()),
                List.of(a.getId(), -1L), Arrays.asList(a.getId(), null), List.<Long>of())) {
            mvc.perform(put("/game-categories/display-order").contentType(MediaType.APPLICATION_JSON)
                .content(json.writeValueAsString(java.util.Map.of("categoryIds", invalid))))
                .andExpect(status().isBadRequest());
            assertThat(categories.listOrdered()).extracting(GameCategory::getId).containsExactlyElementsOf(original);
        }
        String reverse = json.writeValueAsString(java.util.Map.of("categoryIds", List.of(b.getId(), a.getId())));
        jdbc.execute("ALTER TABLE game_category ADD CONSTRAINT ui_order_failure CHECK (id <> " + a.getId() + " OR display_order <> 1)");
        try {
            mvc.perform(put("/game-categories/display-order").contentType(MediaType.APPLICATION_JSON).content(reverse))
                .andExpect(status().is5xxServerError());
            assertThat(categories.listOrdered()).extracting(GameCategory::getId).containsExactlyElementsOf(original);
        } finally { jdbc.execute("ALTER TABLE game_category DROP CONSTRAINT ui_order_failure"); }
        mvc.perform(put("/game-categories/display-order").contentType(MediaType.APPLICATION_JSON).content(reverse))
            .andExpect(status().isOk()).andExpect(jsonPath("$.data[0].id").value(b.getId()));
        mvc.perform(get("/game-categories"))
            .andExpect(jsonPath("$.data[0].name").value("UI B"))
            .andExpect(jsonPath("$.data[0].cover").value("b.png"))
            .andExpect(jsonPath("$.data[1].id").value(a.getId()));
    }

    @Test void spriteColorsPersistAndPointEditingKeepsColor() throws Exception {
        for (int color = 0; color < 4; color++) {
            String response = mvc.perform(post("/spirit").contentType(MediaType.APPLICATION_JSON)
                .content("{\"name\":\"UI color " + color + "\",\"width\":2,\"height\":2,\"points\":[[0,0]],\"color\":" + color + "}"))
                .andExpect(status().isOk()).andExpect(jsonPath("$.data.color").value(color))
                .andReturn().getResponse().getContentAsString();
            String id = json.readTree(response).path("data").path("id").asText();
            spirits.updatePoints(id, new SpiritUpdateReq(2, 2, List.of(List.of(1, 1))));
            assertThat(spirits.getById(id).getColor()).isEqualTo(color);
            mvc.perform(get("/spirit" )).andExpect(status().isOk());
        }
        mvc.perform(post("/spirit").contentType(MediaType.APPLICATION_JSON)
            .content("{\"name\":\"UI legacy\",\"width\":1,\"height\":1,\"points\":[]}"))
            .andExpect(status().isOk()).andExpect(jsonPath("$.data.color").value(0));
    }

    @Test void invalidColorDoesNotWrite() throws Exception {
        long before = spirits.count();
        for (String color : List.of("-1", "4", "1.5", "\"red\"", "\"2\"", "true", "{}", "[]")) {
            mvc.perform(post("/spirit").contentType(MediaType.APPLICATION_JSON)
                .content("{\"name\":\"invalid\",\"width\":1,\"height\":1,\"points\":[],\"color\":" + color + "}"))
                .andExpect(status().isBadRequest());
        }
        assertThat(spirits.count()).isEqualTo(before);
    }

    private GameCategory createCategory(String name, String cover) {
        GameCategory item = new GameCategory(); item.setName(name); item.setCover(cover);
        return categories.create(item);
    }
}

