+// Reorder only the displayed slots; hidden/other-category records stay put.
+export function reorderVisibleSlots(items, visibleIds, sourceId, targetId) {
+  const ids = visibleIds.map(String);
+  const from = ids.indexOf(String(sourceId));
+  const to = ids.indexOf(String(targetId));
+  if (from < 0 || to < 0 || from === to) return [...items];
+  const nextIds = [...ids];
+  nextIds.splice(to, 0, nextIds.splice(from, 1)[0]);
+  const byId = new Map(items.map(item => [String(item.id), item]));
+  const visible = new Set(ids);
+  let index = 0;
+  return items.map(item => visible.has(String(item.id)) ? byId.get(nextIds[index++]) : item);
+}

export function filterMediaTree(nodes, accept = 'any') {
  return (nodes || []).flatMap(node => {
    if (node.kind === 'directory') {
      const children = filterMediaTree(node.children, accept);
      return children.length ? [{...node, children}] : [];
    }
    const matches = accept === 'any' ? ['image', 'audio', 'video'].includes(node.mediaType) : node.mediaType === accept;
    return node.kind === 'file' && matches ? [node] : [];
  });
}

export function visibleMediaRows(nodes, expanded, depth = 0) {
  return (nodes || []).flatMap(node => [
    {...node, depth},
    ...(node.kind === 'directory' && expanded.has(node.relativePath)
      ? visibleMediaRows(node.children, expanded, depth + 1) : []),
  ]);
}

