import { createI18n } from "vue-i18n";
import { messages } from "./messages.js";

export const DEFAULT_LOCALE = "zh-CN";
export const SUPPORTED_LOCALES = Object.freeze([
  "zh-CN", "en-US", "es-ES", "pt-PT", "fr-FR", "de-DE", "pl-PL",
  "ru-RU", "vi-VN", "it-IT", "cs-CZ", "ko-KR", "ro-RO", "ar-SA",
]);
const STORAGE_KEY = "led-game.locale";
const CHANNEL_NAME = "led-game-language";

export const i18n = createI18n({
  legacy: false,
  locale: DEFAULT_LOCALE,
  fallbackLocale: DEFAULT_LOCALE,
  messages,
  missingWarn: false,
  fallbackWarn: false,
});

let languageApi = null;
let removeLanguageListener = null;
let fallbackChannel = null;

export function normalizeLocale(value) {
  return SUPPORTED_LOCALES.includes(value) ? value : DEFAULT_LOCALE;
}

export function applyLocale(value) {
  const locale = normalizeLocale(value);
  i18n.global.locale.value = locale;
  if (typeof document !== "undefined") {
    document.documentElement.lang = locale;
    document.documentElement.dir = "ltr";
    document.documentElement.dataset.languageDirection = locale === "ar-SA" ? "rtl" : "ltr";
  }
  return locale;
}

export async function initializeApplicationLocale(api = globalThis.window?.appLanguage) {
  languageApi = api || null;
  let initialLocale = DEFAULT_LOCALE;
  try {
    initialLocale = languageApi?.get
      ? await languageApi.get()
      : globalThis.localStorage?.getItem(STORAGE_KEY);
  } catch (_error) {
    initialLocale = DEFAULT_LOCALE;
  }
  applyLocale(initialLocale);

  removeLanguageListener?.();
  removeLanguageListener = languageApi?.onChanged?.((locale) => applyLocale(locale)) || null;

  if (!languageApi && typeof BroadcastChannel !== "undefined") {
    fallbackChannel?.close();
    fallbackChannel = new BroadcastChannel(CHANNEL_NAME);
    fallbackChannel.onmessage = (event) => applyLocale(event.data);
  }
  return i18n.global.locale.value;
}

export async function setApplicationLocale(value) {
  const locale = normalizeLocale(value);
  if (languageApi?.set) {
    const saved = await languageApi.set(locale);
    return applyLocale(saved);
  }
  applyLocale(locale);
  try {
    globalThis.localStorage?.setItem(STORAGE_KEY, locale);
    fallbackChannel?.postMessage(locale);
  } catch (_error) {
    // A blocked storage backend must not prevent an in-memory language change.
  }
  return locale;
}

export function disposeApplicationLocale() {
  removeLanguageListener?.();
  removeLanguageListener = null;
  fallbackChannel?.close();
  fallbackChannel = null;
}
import { normalizeGameList } from "./gameFlowState.js";

export function supportsGameEditor(game) {
  return game?.type === "rank" || game?.type === "default";
}

export function normalizeSupportedGames(value) {
  const seen = new Set();
  return normalizeGameList(value)
    .filter(supportsGameEditor)
    .filter((game) => {
      if (seen.has(game.id)) return false;
      seen.add(game.id);
      return true;
    })
    .sort((left, right) => (Number.isFinite(Number(left.displayOrder)) ? Number(left.displayOrder) : Number.MAX_SAFE_INTEGER)
      - (Number.isFinite(Number(right.displayOrder)) ? Number(right.displayOrder) : Number.MAX_SAFE_INTEGER)
      || Number(left.id) - Number(right.id));
}

export async function loadSupportedGames(api, options = {}) {
  const includeHidden = Boolean(options.includeHidden);
  const listGames = includeHidden ? api?.listManageableGames : api?.listPlayableGames;
  if (!listGames) throw new Error("Playable game list API is unavailable");
  const initializationErrors = [];
  for (const seed of [api.seedSimpleVariants, api.seedRankType1]) {
    if (!seed) continue;
    try {
      await seed();
    } catch (error) {
      initializationErrors.push(error);
    }
  }
  return {
    games: normalizeSupportedGames(await listGames()),
    initializationError: initializationErrors[0] || null,
  };
}
export function normalizeGameCategory(value) {
  if (!value || typeof value !== "object") return null;
  const id = Number(value.id ?? value.categoryId);
  if (!Number.isFinite(id)) return null;
  const name = String(value.name || "").trim();
  if (!name) return null;
  return {
    id,
    name,
    cover: typeof value.cover === "string" ? value.cover.trim() : "",
    displayOrder: Number.isFinite(Number(value.displayOrder)) ? Number(value.displayOrder) : null,
  };
}

export function normalizeGameCategoryList(value) {
  const source = value?.data ?? value;
  if (!Array.isArray(source)) return [];
  const seen = new Set();
  return source
    .map(normalizeGameCategory)
    .filter((category) => {
      if (!category || seen.has(category.id)) return false;
      seen.add(category.id);
