async function startEmbeddedBackend() {
  if (!shouldUseEmbeddedBackend || embeddedBackendProcess) {
    appendStartupLog('Embedded backend skipped')
    return
  }

  const backendJarPath = getEmbeddedBackendJarPath()
  const javaPath = getEmbeddedJavaPath()
  appendStartupLog(`Starting embedded backend with jar=${backendJarPath} java=${javaPath}`)
  if (!nodeFs.existsSync(backendJarPath)) {
    throw new Error(`Embedded backend jar not found: ${backendJarPath}`)
  }
  if (!nodeFs.existsSync(javaPath)) {
    throw new Error(`Embedded Java runtime not found: ${javaPath}`)
  }

  await prepareUserDatabase()

  const backendPort = await findAvailablePort(preferredBackendPort)
  const selectedBackendBaseUrl = `http://127.0.0.1:${backendPort}`
  const savedApplicationSettings = await applicationSettings.get()
  const mediaRoot = getPackagedMediaRoot()
  const elc408ConfigDirectory = getElc408ConfigDirectory()
  const hasElc408Config =
    nodeFs.existsSync(path.join(elc408ConfigDirectory, 'conf.json')) &&
    nodeFs.existsSync(path.join(elc408ConfigDirectory, 'wiring.json'))
  setBackendBaseUrl(selectedBackendBaseUrl)
  appendStartupLog(`Embedded backend selected port ${backendPort}`)
  appendStartupLog(`ELC-408 configuration ${hasElc408Config ? 'found' : 'not found'} at ${elc408ConfigDirectory}`)

  const logsDir = path.join(app.getPath('userData'), 'logs')
  await fs.mkdir(logsDir, { recursive: true })
  embeddedBackendLogSink = await createBoundedLogSink(path.join(logsDir, 'backend.log'), {
    maxBytes: runtimeLogOptions.backendMaxBytes,
    history: runtimeLogOptions.backendHistory,
    onWarning: (error) => console.warn(`Backend log write failed: ${error.message || String(error)}`),
  })

  embeddedBackendProcess = childProcess.spawn(javaPath, ['-jar', backendJarPath], {
    // Spring resolves ${user.dir}/elc408 against the portable app directory.
    cwd: getEmbeddedBackendWorkingDirectory(),
    windowsHide: true,
    stdio: ['ignore', 'pipe', 'pipe'],
    env: {
      ...process.env,
      SERVER_PORT: String(backendPort),
      // Allow the packaged app to start before the first conf/wiring files are generated.
      ELC408_ENABLED: process.env.ELC408_ENABLED ?? String(hasElc408Config),
      SPRING_DATASOURCE_URL: `jdbc:h2:file:${getUserDatabaseBasePath()};MODE=MySQL;DATABASE_TO_LOWER=TRUE`,
      LED_MEDIA_ROOT: mediaRoot,
      LED_BRIDGE_ENABLED: process.env.LED_BRIDGE_ENABLED || 'false',
      MEMBER_PLATFORM_BASE_URL: `http://${savedApplicationSettings.memberPlatformHost}:${savedApplicationSettings.memberPlatformPort}`,
      LED_ROOM_CONNECTION_ENABLED: process.env.LED_ROOM_CONNECTION_ENABLED ?? 'true',
    },
  })
  const spawnedBackend = embeddedBackendProcess
  spawnedBackend.stdout.pipe(embeddedBackendLogSink, { end: false })
  spawnedBackend.stderr.pipe(embeddedBackendLogSink, { end: false })

  spawnedBackend.once('exit', (code, signal) => {
    const message = `Embedded backend exited: code=${code ?? 'null'} signal=${signal ?? 'null'}`
    console.warn(message)
    appendStartupLog(message)
    if (embeddedBackendProcess === spawnedBackend) {
      embeddedBackendProcess = null
    }
    closeEmbeddedBackendLogSink(spawnedBackend)
  })

  await waitForBackend(selectedBackendBaseUrl)
  appendStartupLog('Embedded backend is ready')
}

function stopEmbeddedBackend() {
  if (embeddedBackendProcess) {
    const processToStop = embeddedBackendProcess
    embeddedBackendProcess = null
    closeEmbeddedBackendLogSink(processToStop)
    processToStop.kill()
    return processToStop
