package com.ledgame.controller;

import com.ledgame.common.Result;
import com.ledgame.dto.rank.GameMetadataUpdateRequest;
import com.ledgame.dto.rank.GameDisplayOrderUpdateRequest;
import com.ledgame.dto.rank.PlayableGameSummary;
import com.ledgame.entity.Game;
import com.ledgame.service.GameMetadataService;
import com.ledgame.service.PlayableGameCatalogService;
import java.util.List;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/games")
public class GameCatalogController {
    private final PlayableGameCatalogService catalogService;
    private final GameMetadataService metadataService;

    public GameCatalogController(PlayableGameCatalogService catalogService, GameMetadataService metadataService) {
        this.catalogService = catalogService;
        this.metadataService = metadataService;
    }

    @GetMapping("/playable")
    public Result<List<PlayableGameSummary>> playable() {
        return Result.ok(catalogService.list());
    }

    @GetMapping("/manageable")
    public Result<List<PlayableGameSummary>> manageable() {
        return Result.ok(catalogService.listAll());
    }

    @PatchMapping("/{gameId}/metadata")
    public Result<Game> updateMetadata(
            @PathVariable Long gameId,
            @RequestBody GameMetadataUpdateRequest request) {
        return Result.ok(metadataService.update(gameId, request));
    }

    @PutMapping("/display-order")
    public Result<List<PlayableGameSummary>> updateDisplayOrder(
            @RequestBody GameDisplayOrderUpdateRequest request) {
        return Result.ok(catalogService.reorder(request == null ? null : request.gameIds()));
    }
}
