+package com.ledgame.controller;
+
+import static org.assertj.core.api.Assertions.assertThat;
+import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
+import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
+
+import com.fasterxml.jackson.databind.ObjectMapper;
+import com.ledgame.entity.Game;
+import com.ledgame.platform.MemberPlatformChildMode;
+import com.ledgame.service.GameService;
+import java.util.List;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.http.MediaType;
+import org.springframework.jdbc.core.JdbcTemplate;
+import org.springframework.test.web.servlet.MockMvc;
+
+@SpringBootTest(properties = {
+    "spring.datasource.url=jdbc:h2:mem:touch-visibility;MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE",
+    "led.bridge.enabled=false", "led.room-connection.enabled=false"
+})
+@AutoConfigureMockMvc
+class TouchVisibilityIntegrationTest {
+    @Autowired MockMvc mvc;
+    @Autowired ObjectMapper json;
+    @Autowired GameService games;
+    @Autowired MemberPlatformChildMode childMode;
+    @Autowired JdbcTemplate jdbc;
+    @Autowired com.ledgame.service.SimpleGameVariantSeedService simpleSeed;
+    @Autowired com.ledgame.service.RankType1SeedService rankSeed;
+
+    @Test void perGameVisibilityPersistsForAllPlayStylesAndIgnoresStoreMode() throws Exception {
+        simpleSeed.seed();
+        rankSeed.seed();
+        List<Long> playable = ids("/games/playable");
+        assertThat(playable).hasSizeGreaterThanOrEqualTo(4);
+        for (Long id : playable) {
+            Game before = games.getById(id);
+            updateVisibility(id, "{\"childModeVisible\":false}");
+            assertThat(games.getById(id).getName()).isEqualTo(before.getName());
+            for (boolean mode : List.of(false, true)) {
+                childMode.update(mode);
+                assertThat(ids("/games/playable")).doesNotContain(id);
+                assertThat(ids("/games/manageable")).contains(id);
+            }
+            updateVisibility(id, "{\"childModeVisible\":true}");
+            assertThat(ids("/games/playable")).contains(id);
+            updateVisibility(id, "{\"description\":\"unrelated metadata\"}");
+            assertThat(games.getById(id).getChildModeVisible()).isTrue();
+            jdbc.update("UPDATE game SET child_mode_visible=NULL WHERE id=?", id);
+            assertThat(ids("/games/playable")).contains(id);
+            updateVisibility(id, "{\"childModeVisible\":true}");
+        }
+    }
+
+    private void updateVisibility(Long id, String body) throws Exception {
+        mvc.perform(patch("/games/" + id + "/metadata").contentType(MediaType.APPLICATION_JSON).content(body))
+                .andExpect(status().isOk());
+    }
+
+    private List<Long> ids(String route) throws Exception {
+        var data = json.readTree(mvc.perform(get(route)).andExpect(status().isOk())
+                .andReturn().getResponse().getContentAsString()).path("data");
+        java.util.ArrayList<Long> result = new java.util.ArrayList<>();
+        data.forEach(item -> result.add(item.path("gameId").asLong()));
+        return result;
+    }
+}
