import com.ledgame.entity.GameCategory;
import com.ledgame.service.GameCategoryService;
import com.ledgame.service.SpiritService;
import java.util.Arrays;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;

@SpringBootTest(properties = {
    "spring.datasource.url=jdbc:h2:mem:catalog-library-ui;MODE=MySQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE",
    "led.bridge.enabled=false"
})
@AutoConfigureMockMvc
class CatalogLibraryUiIntegrationTest {
    @Autowired MockMvc mvc;
    @Autowired ObjectMapper json;
    @Autowired GameCategoryService categories;
    @Autowired SpiritService spirits;
    @Autowired JdbcTemplate jdbc;

    @Test void categoryOrderIsAtomicAndPreservesMetadata() throws Exception {
        categories.remove(new com.baomidou.mybatisplus.core.conditions.query.QueryWrapper<>());
        GameCategory a = createCategory("UI A", "a.png");
        GameCategory b = createCategory("UI B", "b.png");
        List<Long> original = List.of(a.getId(), b.getId());
        for (List<Long> invalid : Arrays.asList(List.of(a.getId()), List.of(a.getId(), a.getId()),
                List.of(a.getId(), -1L), Arrays.asList(a.getId(), null), List.<Long>of())) {
            mvc.perform(put("/game-categories/display-order").contentType(MediaType.APPLICATION_JSON)
                .content(json.writeValueAsString(java.util.Map.of("categoryIds", invalid))))
                .andExpect(status().isBadRequest());
            assertThat(categories.listOrdered()).extracting(GameCategory::getId).containsExactlyElementsOf(original);
        }
        String reverse = json.writeValueAsString(java.util.Map.of("categoryIds", List.of(b.getId(), a.getId())));
        jdbc.execute("ALTER TABLE game_category ADD CONSTRAINT ui_order_failure CHECK (id <> " + a.getId() + " OR display_order <> 1)");
        try {
            mvc.perform(put("/game-categories/display-order").contentType(MediaType.APPLICATION_JSON).content(reverse))
                .andExpect(status().is5xxServerError());
            assertThat(categories.listOrdered()).extracting(GameCategory::getId).containsExactlyElementsOf(original);
