    void defaultsMatchGuide() {
        Elc408Configuration configuration = new Elc408Configuration();
        assertThat(configuration.getSchemaVersion()).isEqualTo(1);
        assertThat(configuration.getTcpServerPort()).isEqualTo(3002);
        assertThat(configuration.isAllowRepeatActiveOnDown()).isFalse();
        assertThat(configuration.getDebounceMillis()).isEqualTo(50);
        assertThat(configuration.getControllerModel()).isEqualTo(Elc408Configuration.ControllerModel.HC08);
        assertThat(configuration.getRgbMode()).isEqualTo(Elc408Configuration.RgbMode.RGB);
    }

    @Test
    void rejectsOutOfRangePort() {
        Elc408Configuration configuration = new Elc408Configuration();
        configuration.setTcpServerPort(70_000);
        assertThatThrownBy(configuration::validate)
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("tcpServerPort");
    }

    @Test
    void rejectsNegativeDebounce() {
        Elc408Configuration configuration = new Elc408Configuration();
        configuration.setDebounceMillis(-1);
        assertThatThrownBy(configuration::validate)
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("debounceMillis");
    }

