        assertThat(Elc408Configuration.RgbMode.RGB.componentOrder()).containsExactly(0, 1, 2);
        assertThat(Elc408Configuration.RgbMode.GRB.componentOrder()).containsExactly(1, 0, 2);
        assertThat(Elc408Configuration.RgbMode.BRG.componentOrder()).containsExactly(2, 0, 1);
        assertThat(Elc408Configuration.RgbMode.BGR.componentOrder()).containsExactly(2, 1, 0);
    }

