        assertThat(Elc408Configuration.RgbMode.parse("rgb")).isEqualTo(Elc408Configuration.RgbMode.RGB);
        assertThat(Elc408Configuration.RgbMode.parse("GrB")).isEqualTo(Elc408Configuration.RgbMode.GRB);
        assertThat(Elc408Configuration.RgbMode.parse("invalid")).isNull();
    }

