package com.ledgame.service;

import com.ledgame.GameApp.Runtime.GameRuntimeFactoryRegistry;
import com.ledgame.dto.rank.PlayableGameSummary;
import com.ledgame.dto.rank.RankGameEditorDocument;
import com.ledgame.entity.Game;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.stereotype.Service;
import com.ledgame.platform.MemberPlatformChildMode;

@Service
public class PlayableGameCatalogService {
    private final GameService gameService;
    private final GameRuntimeFactoryRegistry registry;
    private final RankGameDocumentMapper rankMapper;
    private final RankGameValidator rankValidator;
    private final MemberPlatformChildMode childMode;

    public PlayableGameCatalogService(
            GameService gameService,
            GameRuntimeFactoryRegistry registry,
            RankGameDocumentMapper rankMapper,
            RankGameValidator rankValidator,
            MemberPlatformChildMode childMode) {
        this.gameService = gameService;
        this.registry = registry;
        this.rankMapper = rankMapper;
        this.rankValidator = rankValidator;
        this.childMode = childMode;
    }

    public List<PlayableGameSummary> list() {
        return list(false);
    }

    public List<PlayableGameSummary> listAll() {
        return list(true);
    }

    private List<PlayableGameSummary> list(boolean includeChildHidden) {
        List<PlayableGameSummary> result = new ArrayList<>();
        for (Game game : orderedGames()) {
            if (!includeChildHidden && !childMode.isGameVisible(game)) continue;
            try {
                registry.find(game);
                result.add(toSummary(game));
            } catch (RuntimeException ignored) {
                // Unsupported or invalid games stay out of player-facing lists.
            }
        }
        return List.copyOf(result);
    }

    private PlayableGameSummary toSummary(Game game) {
        if (RankGameDocumentMapper.TYPE.equals(game.getType())) {
            RankGameEditorDocument document = rankMapper.toDocument(game);
            if (rankValidator.validate(document).hasErrors()) {
                throw new IllegalArgumentException("invalid Rank game: " + game.getId());
            }
            List<PlayableGameSummary.LevelSummary> levels = new ArrayList<>();
            for (int index = 0; index < document.getLevels().size(); index++) {
                RankGameEditorDocument.Level level = document.getLevels().get(index);
                levels.add(new PlayableGameSummary.LevelSummary(index, level.getLabel(), level.getDurationSeconds()));
            }
            return new PlayableGameSummary(
                    game.getId(), game.getName(), document.getDisplayName(), childModeVisible(game), game.getType(), game.getMode(),
                    game.getCover(), game.getDescription(), game.getFirstCatalog(), game.getSiteSizeWidth(), game.getSiteSizeHeight(),
                    document.getMinPlayers(), document.getMaxPlayers(), game.getDisplayOrder(), List.copyOf(levels));
        }
        return new PlayableGameSummary(
                game.getId(), game.getName(), game.getName(), childModeVisible(game), game.getType(), game.getMode(), game.getCover(),
                game.getDescription(), game.getFirstCatalog(), game.getSiteSizeWidth(), game.getSiteSizeHeight(), 1,
                game.getParticipants() == null ? 1 : game.getParticipants(), game.getDisplayOrder(), simpleLevels(game));
    }

    private boolean childModeVisible(Game game) {
        return !Boolean.FALSE.equals(game.getChildModeVisible());
    }

    @Transactional
    public List<PlayableGameSummary> reorder(List<Long> requestedIds) {
        if (requestedIds == null || requestedIds.isEmpty()) {
            throw new IllegalArgumentException("游戏顺序不能为空");
        }
        Set<Long> unique = new HashSet<>(requestedIds);
        if (unique.size() != requestedIds.size() || unique.contains(null)) {
            throw new IllegalArgumentException("游戏顺序不能包含空值或重复 id");
        }
        List<Game> current = orderedGames();
        Set<Long> existingIds = current.stream().map(Game::getId).collect(java.util.stream.Collectors.toSet());
        if (!existingIds.containsAll(unique)) {
            throw new IllegalArgumentException("游戏顺序包含不存在的游戏");
        }
        List<Long> finalIds = new ArrayList<>(requestedIds);
        current.stream().map(Game::getId).filter(id -> !unique.contains(id)).forEach(finalIds::add);
        java.util.Map<Long, Game> byId = current.stream()
                .collect(java.util.stream.Collectors.toMap(Game::getId, game -> game));
        for (int index = 0; index < finalIds.size(); index++) {
            Game game = byId.get(finalIds.get(index));
            game.setDisplayOrder(index);
            if (!gameService.updateById(game)) {
                throw new IllegalStateException("保存游戏顺序失败");
            }
        }
        return list();
    }

    private List<Game> orderedGames() {
        return gameService.list().stream()
                .sorted(Comparator.comparing(Game::getDisplayOrder,
                                Comparator.nullsLast(Integer::compareTo))
                        .thenComparing(Game::getId, Comparator.nullsLast(Long::compareTo)))
                .toList();
    }

    private List<PlayableGameSummary.LevelSummary> simpleLevels(Game game) {
        try {
            com.fasterxml.jackson.databind.JsonNode root = new com.fasterxml.jackson.databind.ObjectMapper()
                    .readTree(game.getLevels());
            List<PlayableGameSummary.LevelSummary> levels = new ArrayList<>();
            if (root.isArray()) {
                for (int index = 0; index < root.size(); index++) {
                    com.fasterxml.jackson.databind.JsonNode level = root.get(index);
                    levels.add(new PlayableGameSummary.LevelSummary(
                            index,
                            level.path("label").asText("Level " + (index + 1)),
                            level.path("option").path("timeLimitValue").isNumber()
                                    ? level.path("option").path("timeLimitValue").asInt() : null));
                }
            }
            return List.copyOf(levels);
        } catch (Exception ignored) {
            return List.of();
        }
    }
}

