package com.ledgame.service;

import com.ledgame.GameApp.Runtime.GameCallbackService;
import com.ledgame.GameApp.Runtime.GameContext;
import com.ledgame.GameApp.Runtime.GameEngine;
import com.ledgame.GameApp.Runtime.GameLaunchOptions;
import com.ledgame.GameApp.Runtime.GamePreparationSession;
import com.ledgame.GameApp.Runtime.GameRuntimeFactoryRegistry;
import com.ledgame.GameApp.Runtime.StageFailurePolicy;
import com.ledgame.dto.GamePreparationCreateReq;
import com.ledgame.dto.GamePreparationGameReq;
import com.ledgame.dto.GamePreparationUpdateReq;
import com.ledgame.dto.GameStartReq;
import com.ledgame.entity.Game;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import org.springframework.stereotype.Service;
import com.ledgame.platform.MemberGameAccessCoordinator;
import com.ledgame.platform.RoomConnectionClient;
import com.ledgame.platform.MemberPlatformChildMode;

@Service
public class GameLaunchService {
    private final GameService gameService;
    private final GameRuntimeFactoryRegistry runtimeFactoryRegistry;
    private final GameCallbackService gameCallbackService;
    private final GameRuntimeStateService stateService;
    private final MemberGameAccessCoordinator memberAccessCoordinator;
    private RoomConnectionClient roomConnectionClient;
    private MemberPlatformChildMode childMode;

    @org.springframework.beans.factory.annotation.Autowired(required = false)
    public void setChildMode(MemberPlatformChildMode childMode) {
        this.childMode = childMode;
    }

    @org.springframework.beans.factory.annotation.Autowired
    public GameLaunchService(
            GameService gameService,
            GameRuntimeFactoryRegistry runtimeFactoryRegistry,
            GameCallbackService gameCallbackService,
            GameRuntimeStateService stateService,
            MemberGameAccessCoordinator memberAccessCoordinator) {
        this.gameService = gameService;
        this.runtimeFactoryRegistry = runtimeFactoryRegistry;
        this.gameCallbackService = gameCallbackService;
        this.stateService = stateService;
        this.memberAccessCoordinator = memberAccessCoordinator;
    }

    public Map<String, Object> start(GameStartReq request) {
        GamePreparationSession session = createSelectedPreparation(request);
        try {
            return confirm(session.sessionId());
        } catch (RuntimeException | Error error) {
            if (GameEngine.getActivePreparation() == session) {
                GameEngine.cancelPreparation(session.sessionId());
            }
            memberAccessCoordinator.cancel(session.sessionId());
            throw error;
        }
    }

    public Map<String, Object> prepare(GamePreparationCreateReq request) {
        GamePreparationCreateReq normalized = request == null ? new GamePreparationCreateReq() : request;
        Game game = normalized.getGameId() == null ? null : requireGame(normalized.getGameId());
        if (game == null && normalized.getStageFailurePolicy() != null) {
            throw new IllegalArgumentException("请先选择游戏再配置关卡失败策略");
        }
        GamePreparationSession session = GameEngine.prepareGame(game, normalized.toLaunchOptions());
        try {
            memberAccessCoordinator.activate(session);
            return stateService.state();
        } catch (RuntimeException | Error error) {
            if (GameEngine.getActivePreparation() == session) GameEngine.cancelPreparation(session.sessionId());
            memberAccessCoordinator.cancel(session.sessionId());
            throw error;
        }
    }

    public Map<String, Object> selectPreparationGame(
            String sessionId,
            GamePreparationGameReq request) {
        if (request == null || request.getGameId() == null) {
            throw new IllegalArgumentException("游戏 id 不能为空");
        }
        GamePreparationSession current = requireActivePreparation(sessionId);
        Game selectedGame = requireGame(request.getGameId());
        requireVisible(selectedGame);
        GameLaunchOptions options = current.options();
        if (current.game() != null && !Objects.equals(current.game().getId(), selectedGame.getId())) {
            options = withStageFailurePolicy(options, StageFailurePolicy.END_GAME);
        }
        GameEngine.selectPreparationGame(sessionId, selectedGame, options);
        return stateService.state();
    }

    public synchronized Map<String, Object> updatePreparation(
            String sessionId,
            GamePreparationUpdateReq request) {
        if (request == null) {
            throw new IllegalArgumentException("游戏准备更新请求不能为空");
        }
        GamePreparationSession current = requireActivePreparation(sessionId);
        if (request.getStageFailurePolicy() != null && current.game() == null) {
            throw new IllegalArgumentException("请先选择游戏再配置关卡失败策略");
        }
        GameLaunchOptions updated = request.applyTo(current.options());
        memberAccessCoordinator.activate(current.withOptions(updated));
        GamePreparationSession updatedSession = GameEngine.updatePreparation(sessionId, updated);
        return stateService.state();
    }

    public Map<String, Object> confirm(String sessionId) {
        GamePreparationSession activeSession = GameEngine.getActivePreparation();
        if (activeSession == null || !activeSession.sessionId().equals(sessionId)) {
            // Preserve the engine's established stale-session error contract.
            GameEngine.confirmPreparation(sessionId);
            throw new IllegalStateException("unreachable");
        }
        if (activeSession.game() == null) {
            throw new IllegalArgumentException("请先选择游戏再确认开始");
        }
        requireVisible(activeSession.game());
        var factory = runtimeFactoryRegistry.find(activeSession.game());
        factory.prepare(activeSession.game(), activeSession.options());
        memberAccessCoordinator.startPlay(activeSession, activeSession.game());
        GamePreparationSession session = GameEngine.confirmPreparation(sessionId);
        try {
            Game game = session.game();
            GameLaunchOptions options = session.options();
            gameCallbackService.beforeStart(game, options);
            GameContext context = factory.createContext(game, options);
            context.setLaunchOptions(options);
            memberAccessCoordinator.attachContext(session.sessionId(), context);
            gameCallbackService.onStart(context);
            GameEngine.startPreparedGame(session.sessionId(), context);
            if (roomConnectionClient != null) roomConnectionClient.publishEvent("GAME_STARTED");
            return stateService.state();
        } catch (RuntimeException | Error e) {
            memberAccessCoordinator.startupAbort(session.sessionId(), e);
            if (GameEngine.getPendingPreparation() == session) {
                GameEngine.abortPreparedGame(session.sessionId());
            }
            throw e;
        }
    }

    @org.springframework.beans.factory.annotation.Autowired(required = false)
    public void setRoomConnectionClient(RoomConnectionClient roomConnectionClient) {
        this.roomConnectionClient = roomConnectionClient;
    }

    public Map<String, Object> startQueued(GameQueueItem item) {
        if (item == null || item.gameId() == null) throw new IllegalArgumentException("queue item is invalid");
        GameStartReq request = new GameStartReq();
        request.setId(item.gameId());
        request.setIcList(item.options().icList());
        request.setUserCount(item.options().userCount());
        request.setStartLevelIndex(item.options().startLevelIndex());
        request.setTokenList(List.of(item.wristbandUid()));
        request.setIsAdmin(item.options().isAdmin());
        request.setLaunchMethod("wristband");
        request.setStageFailurePolicy(item.options().stageFailurePolicy());
        request.setRuntimeMode(item.options().runtimeMode().name());
        return start(request);
    }

    public Map<String, Object> cancel(String sessionId) {
        GameEngine.cancelPreparation(sessionId);
        memberAccessCoordinator.cancel(sessionId);
        return stateService.state();
    }

    private GamePreparationSession createSelectedPreparation(GameStartReq request) {
        if (request == null || request.getId() == null) {
            throw new IllegalArgumentException("游戏 id 不能为空");
        }
        Game game = requireGame(request.getId());
        GameLaunchOptions options = GameLaunchOptions.from(request);
        GamePreparationSession session = GameEngine.prepareGame(game, options);
        try {
            memberAccessCoordinator.activate(session);
            return session;
        } catch (RuntimeException | Error error) {
            if (GameEngine.getActivePreparation() == session) GameEngine.cancelPreparation(session.sessionId());
            memberAccessCoordinator.cancel(session.sessionId());
            throw error;
        }
    }

    private GamePreparationSession requireActivePreparation(String sessionId) {
        GamePreparationSession current = GameEngine.getActivePreparation();
        if (current == null || !current.sessionId().equals(sessionId)) {
            throw new IllegalArgumentException("游戏准备会话已失效: " + sessionId);
        }
        return current;
    }

    private Game requireGame(Long gameId) {
        Game game = gameService.getById(gameId);
        if (game == null) {
            throw new IllegalArgumentException("游戏不存在: " + gameId);
        }
        return game;
    }

    private void requireVisible(Game game) {
        if (childMode != null && !childMode.isGameVisible(game)) {
            throw new IllegalArgumentException("当前门店设置已隐藏该游戏，请重新选择");
        }
    }

    private GameLaunchOptions withStageFailurePolicy(
            GameLaunchOptions options,
            StageFailurePolicy stageFailurePolicy) {
        return new GameLaunchOptions(
                options.icList(),
                options.userCount(),
                options.startLevelIndex(),
                options.tokenList(),
                options.isAdmin(),
                options.launchMethod(),
                stageFailurePolicy,
                options.runtimeMode());
    }
}

