.elc408-capture-state.active {
  color: var(--ui-success);
  background: var(--ui-active);
}
.elc408-capture-state.failed {
  color: var(--ui-error);
  background: var(--ui-surface);
}
.elc408-log-truncated {
  margin-left: 6px;
  color: var(--ui-text-secondary);
  font-family: inherit;
  font-size: 0.68rem;
}
.elc408-debug-log header button {
  min-height: 32px;
  padding: 0 12px;
  border: 1px solid var(--ui-border);
  border-radius: 6px;
  color: var(--ui-text-secondary);
  background: var(--ui-surface);
  cursor: pointer;
  font-size: 0.78rem;
  font-weight: 650;
}
.elc408-log-table-wrap {
  flex: 1;
  min-height: 0;
  border: 1px solid var(--ui-border);
  border-radius: 6px;
  background: var(--ui-surface);
  overflow: auto;
}
.elc408-debug-log table {
  width: 100%;
  border-collapse: collapse;
  color: var(--ui-text-secondary);
  font-size: 0.77rem;
}
.elc408-debug-log th,
.elc408-debug-log td {
  padding: 8px 10px;
  text-align: left;
  border-bottom: 1px solid var(--ui-border);
  vertical-align: top;
}
.elc408-debug-log th {
  position: sticky;
  top: 0;
  z-index: 1;
  color: var(--ui-text-secondary);
  background: var(--ui-surface);
  font-size: 0.72rem;
  font-weight: 750;
  text-transform: uppercase;
}
.elc408-debug-log tbody tr:hover {
  background: var(--ui-active);
}
.elc408-hex {
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  min-width: 0;
}
.elc408-hex-row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
}
.elc408-hex-value {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.elc408-hex-value.expanded {
  overflow: visible;
  white-space: normal;
  overflow-wrap: anywhere;
}
.elc408-log-expand {
  flex: 0 0 auto;
  width: 30px;
  min-height: 24px;
  padding: 0 4px;
  border: 1px solid var(--ui-border);
  border-radius: 4px;
  color: var(--ui-text-secondary);
  background: var(--ui-surface);
  cursor: pointer;
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 0.72rem;
  line-height: 1;
}
.elc408-log-expand:hover {
  border-color: var(--ui-border-strong);
  color: var(--ui-accent);
  background: var(--ui-active);
}
.elc408-log-expand:focus-visible {
  outline: 2px solid var(--ui-accent);
  outline-offset: 1px;
}
.elc408-debug-log .send {
  color: var(--ui-warning);
  font-weight: 700;
}
.elc408-debug-log .receive {
  color: var(--ui-success);
  font-weight: 700;
}
.elc408-success {
  margin: 0;
  color: var(--ui-success);
  font-size: 0.8rem;
}
.elc408-error {
  margin: 0;
  color: var(--ui-error);
  font-size: 0.8rem;
}
.elc408-send-hint {
  margin: 0;
  color: var(--ui-muted);
  font-size: 0.75rem;
}
@media (max-width: 760px) {
  .elc408-debug-panel {
    flex-direction: column;
    height: auto;
  }
  .elc408-debug-controls {
    width: 100%;
    flex: none;
    overflow: visible;
  }
  .elc408-debug-log {
    flex: none;
    height: 520px;
  }
}
