package com.ledgame.hardware.elc408.config;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

class Elc408ConfigurationTest {

    @Test
    void defaultsMatchGuide() {
        Elc408Configuration configuration = new Elc408Configuration();
        assertThat(configuration.getSchemaVersion()).isEqualTo(1);
        assertThat(configuration.getTcpServerPort()).isEqualTo(3002);
        assertThat(configuration.isAllowRepeatActiveOnDown()).isFalse();
        assertThat(configuration.getDebounceMillis()).isEqualTo(50);
        assertThat(configuration.getControllerModel()).isEqualTo(Elc408Configuration.ControllerModel.HC08);
        assertThat(configuration.getRgbMode()).isEqualTo(Elc408Configuration.RgbMode.RGB);
    }

    @Test
    void rejectsOutOfRangePort() {
        Elc408Configuration configuration = new Elc408Configuration();
        configuration.setTcpServerPort(70_000);
        assertThatThrownBy(configuration::validate)
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("tcpServerPort");
    }

    @Test
    void rejectsNegativeDebounce() {
        Elc408Configuration configuration = new Elc408Configuration();
        configuration.setDebounceMillis(-1);
        assertThatThrownBy(configuration::validate)
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("debounceMillis");
    }

    @Test
    void controllerModelDerivesChannels() {
        assertThat(Elc408Configuration.ControllerModel.HC08.channelsPerController()).isEqualTo(8);
        assertThat(Elc408Configuration.ControllerModel.HC04.channelsPerController()).isEqualTo(4);
    }

    @Test
    void rgbModeProvidesComponentOrder() {
        assertThat(Elc408Configuration.RgbMode.RGB.componentOrder()).containsExactly(0, 1, 2);
        assertThat(Elc408Configuration.RgbMode.GRB.componentOrder()).containsExactly(1, 0, 2);
        assertThat(Elc408Configuration.RgbMode.BRG.componentOrder()).containsExactly(2, 0, 1);
        assertThat(Elc408Configuration.RgbMode.BGR.componentOrder()).containsExactly(2, 1, 0);
    }

    @Test
    void parsesRgbModeCaseInsensitive() {
        assertThat(Elc408Configuration.RgbMode.parse("rgb")).isEqualTo(Elc408Configuration.RgbMode.RGB);
        assertThat(Elc408Configuration.RgbMode.parse("GrB")).isEqualTo(Elc408Configuration.RgbMode.GRB);
        assertThat(Elc408Configuration.RgbMode.parse("invalid")).isNull();
    }

