package com.ledgame.service;

import com.ledgame.dto.rank.GameMetadataUpdateRequest;
import com.ledgame.entity.Game;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;

@Service
public class GameMetadataService {
    private final GameService gameService;

    public GameMetadataService(GameService gameService) {
        this.gameService = gameService;
    }

    @Transactional
    public Game update(Long gameId, GameMetadataUpdateRequest request) {
        Game game = gameService.getById(gameId);
        if (game == null) throw new IllegalArgumentException("游戏不存在: " + gameId);
        if (request == null) throw new IllegalArgumentException("元数据更新内容不能为空");
        if (request.getName() != null) {
            String name = request.getName().trim();
            if (name.isEmpty()) throw new IllegalArgumentException("游戏名称不能为空");
            if (name.length() > 255) throw new IllegalArgumentException("游戏名称不能超过 255 个字符");
            boolean duplicate = gameService.list().stream()
                    .anyMatch(item -> !item.getId().equals(gameId)
                            && item.getName() != null && item.getName().trim().equalsIgnoreCase(name));
            if (duplicate) throw new IllegalArgumentException("游戏名称已存在: " + name);
            game.setName(name);
        }
        if (request.getDisplayName() != null) game.setRemark(request.getDisplayName().trim());
        if (request.getDescription() != null) game.setDescription(request.getDescription());
        if (request.getCover() != null) game.setCover(request.getCover());
        if (request.getChildModeVisible() != null) game.setChildModeVisible(request.getChildModeVisible());
        if (request.getFirstCatalog() != null) game.setFirstCatalog(request.getFirstCatalog().trim());
        gameService.updateById(game);
        return game;
    }
}

