  const sessionId = preparation.value?.sessionId;
  if (!sessionId || !game?.id) return;
  const result = await runAction(
    "select-game",
    () => api.selectPreparationGame(sessionId, game.id),
    { refreshOnError: true },
  );
  if (result) {
    draft.userCount =
      runtimeState.value.preparation?.options.userCount ??
      game.participants ??
      1;
  }
}

