import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.ledgame.dto.rank.GameMetadataUpdateRequest;
import com.ledgame.entity.Game;
import java.util.List;
import org.junit.jupiter.api.Test;

class GameMetadataServiceTest {
    @Test
    void trimsTheNameAndPreservesIdentityAndDisplayOrder() {
        GameService games = mock(GameService.class);
        Game game = game(4L, "old", 8);
        when(games.getById(4L)).thenReturn(game);
        when(games.list()).thenReturn(List.of(game));
        GameMetadataUpdateRequest request = new GameMetadataUpdateRequest();
        request.setName("  new name  ");

        Game updated = new GameMetadataService(games).update(4L, request);

        assertThat(updated.getName()).isEqualTo("new name");
        assertThat(updated.getId()).isEqualTo(4L);
        assertThat(updated.getDisplayOrder()).isEqualTo(8);
        verify(games).updateById(game);
    }

    @Test
    void updatesChildModeVisibilityWithoutChangingOtherMetadata() {
        GameService games = mock(GameService.class);
        Game game = game(4L, "old", 8);
        game.setChildModeVisible(true);
        when(games.getById(4L)).thenReturn(game);
        when(games.list()).thenReturn(List.of(game));
        GameMetadataUpdateRequest request = new GameMetadataUpdateRequest();
        request.setChildModeVisible(false);

        Game updated = new GameMetadataService(games).update(4L, request);

        assertThat(updated.getChildModeVisible()).isFalse();
        assertThat(updated.getName()).isEqualTo("old");
        verify(games).updateById(game);
    }

    @Test
    void updatesThePrimaryMenuWithoutChangingGameIdentity() {
        GameService games = mock(GameService.class);
        Game game = game(4L, "old", 8);
        when(games.getById(4L)).thenReturn(game);
        when(games.list()).thenReturn(List.of(game));
        GameMetadataUpdateRequest request = new GameMetadataUpdateRequest();
        request.setFirstCatalog("  12  ");

        Game updated = new GameMetadataService(games).update(4L, request);

        assertThat(updated.getFirstCatalog()).isEqualTo("12");
        assertThat(updated.getName()).isEqualTo("old");
        verify(games).updateById(game);
    }

    @Test
    void rejectsBlankLongAndCaseInsensitiveDuplicateNamesWithoutWriting() {
        GameService games = mock(GameService.class);
        Game game = game(4L, "old", 8);
        when(games.getById(4L)).thenReturn(game);
        when(games.list()).thenReturn(List.of(game, game(5L, "Taken", 9)));
        GameMetadataService service = new GameMetadataService(games);

        for (String invalid : List.of("   ", "x".repeat(256), " taken ")) {
            GameMetadataUpdateRequest request = new GameMetadataUpdateRequest();
            request.setName(invalid);
            assertThatThrownBy(() -> service.update(4L, request))
                    .isInstanceOf(IllegalArgumentException.class);
        }
        verify(games, never()).updateById(game);
    }

    private static Game game(long id, String name, int displayOrder) {
        Game game = new Game();
        game.setId(id);
        game.setName(name);
        game.setDisplayOrder(displayOrder);
        return game;
    }
}

