    private static final class CapturingDatagramSocket extends DatagramSocket {
        private final List<byte[]> packets = new java.util.concurrent.CopyOnWriteArrayList<>();

        private CapturingDatagramSocket() throws SocketException {
            super((java.net.SocketAddress) null);
        }

        @Override
        public void send(DatagramPacket packet) throws IOException {
            packets.add(Arrays.copyOfRange(
                    packet.getData(), packet.getOffset(), packet.getOffset() + packet.getLength()));
        }
    }

    private static final class QueueDatagramSocket extends DatagramSocket {
        private final BlockingQueue<QueuedDatagram> incoming = new LinkedBlockingQueue<>();
        private final CountDownLatch firstSend = new CountDownLatch(1);
        private volatile int timeoutMillis = 500;

        private QueueDatagramSocket() throws SocketException {
            super((java.net.SocketAddress) null);
        }

        CountDownLatch enqueue(byte[] data, String sourceIp) throws IOException {
            CountDownLatch delivered = new CountDownLatch(1);
            incoming.add(new QueuedDatagram(data.clone(), InetAddress.getByName(sourceIp), delivered));
            return delivered;
        }

        @Override
        public void send(DatagramPacket packet) {
            firstSend.countDown();
        }

        @Override
        public void setSoTimeout(int timeout) {
            timeoutMillis = timeout;
        }

        @Override
        public void receive(DatagramPacket packet) throws IOException {
            try {
                QueuedDatagram queued = incoming.poll(timeoutMillis, TimeUnit.MILLISECONDS);
                if (queued == null) {
                    throw new SocketTimeoutException();
                }
                packet.setData(queued.data().clone());
                packet.setLength(queued.data().length);
                packet.setAddress(queued.source());
                packet.setPort(Elc408UdpTransport.CONTROLLER_PORT);
                queued.delivered().countDown();
            } catch (InterruptedException error) {
                Thread.currentThread().interrupt();
                throw new SocketException("interrupted");
            }
        }
    }

    private record QueuedDatagram(byte[] data, InetAddress source, CountDownLatch delivered) {
    }
