$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$packageRoot='F:\project\ledGame\release\win-unpacked'
$archive=[System.IO.Compression.ZipFile]::OpenRead('F:\project\ledGame\release\LED Game-0.1.0-win.zip')
$sha=[System.Security.Cryptography.SHA256]::Create()
try {
  $checked=0
  $entries=@($archive.Entries | Where-Object { -not $_.FullName.EndsWith('/') })
  $diskFiles=@(Get-ChildItem -LiteralPath $packageRoot -File -Recurse)
  if($entries.Count -ne $diskFiles.Count){ throw "File count mismatch: ZIP $($entries.Count), directory $($diskFiles.Count)" }
  foreach($entry in $entries){
    $filePath=Join-Path $packageRoot $entry.FullName
    $file=Get-Item -LiteralPath $filePath
    if($file.Length -ne $entry.Length){throw "Length mismatch: $($entry.FullName)"}
    $zipStream=$entry.Open()
    try {$zipHash=[BitConverter]::ToString($sha.ComputeHash($zipStream))} finally {$zipStream.Dispose()}
    $fileStream=[System.IO.File]::OpenRead($filePath)
    try {$fileHash=[BitConverter]::ToString($sha.ComputeHash($fileStream))} finally {$fileStream.Dispose()}
    if($zipHash -ne $fileHash){throw "SHA256 mismatch: $($entry.FullName)"}
    $checked++
  }
  Write-Output "PASS: $checked files identical by length and SHA256"
} finally {$sha.Dispose();$archive.Dispose()}

